-- 11: oddiy testlarga inglizcha atamalar + 9 ta rasmli test (hammasi bitta)
begin;
update public.tests set questions = $json$[{"id": "q1", "prompt": "Yangi BM (biznes akkaunt) yaratish uchun brauzerda qaysi manzil ochiladi?", "options": [{"id": "a", "text": "facebook.com/pages/create"}, {"id": "b", "text": "instagram.com/business"}, {"id": "c", "text": "business.facebook.com/select"}, {"id": "d", "text": "ads.google.com"}], "explanation": "Videoda ustoz business.facebook.com/select manzilini ochdi. U yerda «Выберите компанию» (Kompaniyani tanlang) sahifasi chiqadi va mavjud BMlar kartochka ko'rinishida turadi.", "correct_option_id": "c"}, {"id": "q2", "prompt": "«Выберите компанию (Select a business)» sahifasida yangi BM yaratish tugmasi qayerda va nima deb yozilgan?", "options": [{"id": "a", "text": "O'ng yuqori burchakda, ko'k «Создать компанию» (Kompaniya yaratish) tugmasi"}, {"id": "b", "text": "Chap pastda, kulrang «Добавить страницу (Add a Page)» tugmasi"}, {"id": "c", "text": "Sahifa o'rtasida, yashil «Начать (Get started)» tugmasi"}, {"id": "d", "text": "Yuqori menyuda, profil rasmi ichida"}], "explanation": "Kartochkalar ustida, o'ng yuqori burchakda ko'k «Создать компанию (Create a business account)» tugmasi turadi.", "correct_option_id": "a"}, {"id": "q3", "prompt": "«Создайте бизнес-аккаунт в Business Manager (Create a business account)» oynasida qaysi 3 ta maydon to'ldiriladi?", "options": [{"id": "a", "text": "Telefon raqami, pasport raqami, manzil"}, {"id": "b", "text": "Kompaniya nomi, ismingiz, ish emailingiz"}, {"id": "c", "text": "Sahifa nomi, logotip, kategoriya"}, {"id": "d", "text": "Karta raqami, valyuta, vaqt mintaqasi"}], "explanation": "Maydonlar: «Название компании и аккаунта» (masalan Murad Buildings), «Ваше имя (Your name)» va «Ваш рабочий электронный адрес (Your business email)». Keyin «Отправить (Submit)» bosiladi.", "correct_option_id": "b"}, {"id": "q4", "prompt": "BM yaratilgach «Аккаунт ... создан!» xabari chiqdi. Keyin nimani tasdiqlash kerak?", "options": [{"id": "a", "text": "Telefon raqamini, SMS kod orqali"}, {"id": "b", "text": "Pasportni, rasm yuklash orqali"}, {"id": "c", "text": "Bank kartasini"}, {"id": "d", "text": "Emailni: Gmailga kelgan «Confirm your business email» xatida «Confirm now» bosiladi"}], "explanation": "Oynada «Подтвердите адрес электронной почты (Confirm your email)» deb yozilgan edi. Ustoz Gmailni ochib, «Confirm your business email» xatidagi «Confirm now» tugmasini bosdi.", "correct_option_id": "d"}, {"id": "q5", "prompt": "Videoda tasdiqlash xati Gmailning qaysi bo'limiga tushgan edi?", "options": [{"id": "a", "text": "Social"}, {"id": "b", "text": "Spam"}, {"id": "c", "text": "Sent (Yuborilganlar)"}, {"id": "d", "text": "Drafts (Qoralamalar)"}], "explanation": "Xat Primary'da emas, Social bo'limida edi. Xat topilmasa, avval Social va Promotions bo'limlarini tekshiring.", "correct_option_id": "a"}, {"id": "q6", "prompt": "Yangi BM yaratilgandan keyin «Создать компанию (Create a business account)» tugmasi xira bo'lib qoldi. Nega?", "options": [{"id": "a", "text": "Internet uzilib qolgani uchun"}, {"id": "b", "text": "Email tasdiqlanmagani uchun"}, {"id": "c", "text": "Facebook akkaunt yangi va ishonch (trust) hali past, shuning uchun ko'proq BM ochishga ruxsat bermaydi"}, {"id": "d", "text": "Bir odam faqat bitta BM ocha oladi"}], "explanation": "Ustozning aytishicha, akkaunt yangi bo'lgani uchun Facebook yangi BM ochishni cheklagan. Akkaunt orqali reklama yurgizib, ishonch oshgach yana BM ochish mumkin bo'ladi.", "correct_option_id": "c"}, {"id": "q7", "prompt": "Email tasdiqlangandan keyin Настройки компании > Пользователи (Business settings > Users) > «Люди (People)» bo'limida o'zingizni qanday holatda ko'rasiz?", "options": [{"id": "a", "text": "«Частичный доступ (Partial access)» va «Неактивный (Inactive)»"}, {"id": "b", "text": "«Полный доступ» (to'liq huquq) va «Активный» (faol)"}, {"id": "c", "text": "«Только просмотр (View only)» va «Ожидает (Pending)»"}, {"id": "d", "text": "Ro'yxatda umuman ko'rinmaysiz"}], "explanation": "Videoda ustoz emailni tasdiqlagach «Люди (People)» bo'limini ochdi: uning ismi yonida «Полный доступ (Full control)» va yashil «Активный (Active)» yozuvi turardi. BMni yaratgan odam avtomatik to'liq huquqli admin bo'ladi.", "correct_option_id": "b"}, {"id": "q8", "prompt": "/select sahifasida kartochkada «Рекламные аккаунты: 0 · Страницы: 2 · Люди: 2 (Ad accounts: 0 · Pages: 2 · People: 2)» yozilgan. Bu nimani bildiradi?", "options": [{"id": "a", "text": "Bu 2 ta alohida BM"}, {"id": "b", "text": "BMga 2 marta kirilgan"}, {"id": "c", "text": "Shu BMda 2 ta reklama akkaunti bor"}, {"id": "d", "text": "Shu BM ichida 2 ta sahifa va 2 ta odam bor, reklama akkaunti hali yo'q"}], "explanation": "Kartochka bitta BMni ko'rsatadi, pastki qatorda esa uning ichidagilar sanaladi. BM ofis bo'lsa, sahifalar undagi peshtaxtalar.", "correct_option_id": "d"}, {"id": "q9", "prompt": "Reklamani qaysi akkaunt orqali yurgizish kerak?", "options": [{"id": "a", "text": "Biznes akkaunt (BM) orqali"}, {"id": "b", "text": "Shaxsiy Facebook profil orqali"}, {"id": "c", "text": "Instagram'dagi «Продвигать (Promote)» tugmasi orqali"}, {"id": "d", "text": "Farqi yo'q"}], "explanation": "Ustoz alohida ta'kidladi: reklamani shaxsiy akkauntdan emas, biznes akkaunt orqali yurgizamiz. BMlar ro'yxatining pastidagi «Ваш аккаунт (Your account)» bu shaxsiy akkaunt.", "correct_option_id": "a"}, {"id": "q10", "prompt": "BMga kirganingizda «Главная» (Bosh sahifa) ochiladi. Chap menyuda qaysi bo'limlar bor edi?", "options": [{"id": "a", "text": "Instagram, WhatsApp, Telegram"}, {"id": "b", "text": "Faqat «Настройки (Settings)»"}, {"id": "c", "text": "Ads Manager, «Отчеты по рекламе (Ads reporting)» va Events Manager"}, {"id": "d", "text": "«Друзья (Friends)», «Группы (Groups)», «Видео (Videos)»"}], "explanation": "Videoda BM ichidagi «Главная (Home)» sahifasida chapda Ads Manager, «Отчеты по рекламе» (Reklama hisobotlari) va Events Manager ko'rindi. O'rtada esa «Результативность рекламного аккаунта (Ad account performance)», «Оповещения (Notifications)» va «Страницы (Pages)» bloklari bor edi.", "correct_option_id": "c"}]$json$::jsonb where id = '3-1';
update public.tests set questions = $json$[{"id": "q1", "prompt": "BMga cheklov tushganini qayerdan bilasiz?", "options": [{"id": "a", "text": "Facebook sahifangizda qizil post chiqadi"}, {"id": "b", "text": "Центр поддержки для бизнеса (Biznes yordam markazi) sahifasida BM nomi ostida qizil «Аккаунт с ограничениями (Restricted account)» yorlig'i turadi"}, {"id": "c", "text": "Instagram profilingiz yopilib qoladi"}, {"id": "d", "text": "BM ro'yxatdan butunlay yo'qoladi"}], "explanation": "Cheklov Центр поддержки для бизнеса > Обзор аккаунта (Business Support Home > Account overview) sahifasida ko'rinadi: BM nomi ostida qizil «Аккаунт с ограничениями» (Cheklovli akkaunt) yorlig'i chiqadi. Gmailga ham «СРОЧНО: Ваш доступ к рекламным функциям ограничен» xati keladi.", "correct_option_id": "b"}, {"id": "q2", "prompt": "Cheklov sahifasida «Запросить проверку» (Tekshiruv so'rash) ko'k tugmasi qaysi blokda turadi?", "options": [{"id": "a", "text": "Chap menyuda, «Пользователи (Users)» bo'limida"}, {"id": "b", "text": "Pastda, «Рекламные аккаунты (0) (Ad accounts (0))» blokida"}, {"id": "c", "text": "O'ng tomonda, «Вот что можно сделать» (Mana nima qilish mumkin) blokida"}, {"id": "d", "text": "Yuqori menyuda, profil rasmi yonida"}], "explanation": "O'ng tomondagi «Вот что можно сделать (Here's what you can do)» blokida ko'k «Запросить проверку (Request review)» tugmasi turadi. Undan pastda «Проверить статус других ваших аккаунтов (Check the status of your other accounts)» bor.", "correct_option_id": "c"}, {"id": "q3", "prompt": "Videoda 3 ta BMdan faqat bittasiga cheklov tushdi. Qaysi biriga va nega?", "options": [{"id": "a", "text": "roas.uz BMsiga, chunki u eng eski"}, {"id": "b", "text": "kitchenshop.uz BMsiga, chunki unda 2 ta sahifa bor"}, {"id": "c", "text": "Uchchalasiga ham bir xil tushdi"}, {"id": "d", "text": "Yangi ochilgan Murad Buildings BMsiga, chunki yangi BMga Facebook roboti avtomatik cheklov qo'yadi"}], "explanation": "Cheklov faqat yangi yaratilgan Murad Buildings BMsiga tushdi. Facebook algoritmi yangi BMga ishonch past bo'lgani uchun ko'pincha avtomatik cheklov qo'yadi. Eski kitchenshop.uz va roas.uz ga tushmadi.", "correct_option_id": "d"}, {"id": "q4", "prompt": "«Запросить проверку (Request review)» bosilgandan keyin qadamlar qaysi tartibda keladi?", "options": [{"id": "a", "text": "Telefon → Robot tekshiruvi → Hujjat → 48 soat"}, {"id": "b", "text": "Robot tekshiruvi (Я не робот) → Telefon kodi → Hujjat yuklash → «48 soat ichida javob»"}, {"id": "c", "text": "Hujjat → Telefon → Robot tekshiruvi → Gmail"}, {"id": "d", "text": "Gmail → Telefon → Robot tekshiruvi → Hujjat"}], "explanation": "Tartib: «Я не робот (I'm not a robot)» → telefon raqami va 6 xonali kod → pasport yoki prava rasmini yuklash → «Мы ответим вам в течение 48 часов (We'll respond within 48 hours)». Natija keyin Gmailga keladi.", "correct_option_id": "b"}, {"id": "q5", "prompt": "Telefon raqamini kiritayotganda mamlakat standart holatda qaysi biri turadi va nima qilish kerak?", "options": [{"id": "a", "text": "AQSh (+1) turadi, uni O'zbekiston (+998) ga o'zgartirish kerak"}, {"id": "b", "text": "Avtomatik O'zbekiston turadi, hech narsa qilish shart emas"}, {"id": "c", "text": "Rossiya (+7) turadi, uni o'zgartirib bo'lmaydi"}, {"id": "d", "text": "Mamlakat tanlanmaydi, faqat raqam yoziladi"}], "explanation": "Videoda standart holatda «Соединенные Штаты Америки (+1) (United States (+1))» turgan edi. Ustoz uni Узбекистан (+998) ga o'zgartirdi.", "correct_option_id": "a"}, {"id": "q6", "prompt": "Tasdiqlash kodi qaysi yo'llar bilan kelishi mumkin, videoda qayerga keldi?", "options": [{"id": "a", "text": "Faqat email orqali"}, {"id": "b", "text": "Faqat Telegram orqali"}, {"id": "c", "text": "SMS yoki WhatsApp orqali. Videoda WhatsAppga keldi"}, {"id": "d", "text": "Faqat qo'ng'iroq orqali"}], "explanation": "Oynada «Отправить через WhatsApp (Send via WhatsApp)» va «Отправить через SMS (Send via SMS)» tugmalari bor edi. Videoda 6 xonali kod WhatsAppga keldi.", "correct_option_id": "c"}, {"id": "q7", "prompt": "Hujjat yuklash qadamida nima yuklanadi?", "options": [{"id": "a", "text": "Kompaniya logotipi"}, {"id": "b", "text": "Shaxsni tasdiqlovchi hujjat rasmi: pasport, haydovchilik guvohnomasi yoki ID karta"}, {"id": "c", "text": "Bank kartasining rasmi"}, {"id": "d", "text": "Sahifaning skrinshoti"}], "explanation": "«Загрузите свое удостоверение личности (Upload your ID)» oynasida pasport, prava yoki boshqa rasmiy hujjat rasmi «Загрузить изображение (Upload image)» orqali yuklanadi.", "correct_option_id": "b"}, {"id": "q8", "prompt": "Hujjatdagi ism Facebook profilingizdagi ismdan farq qilsa, nima bo'lishi mumkin?", "options": [{"id": "a", "text": "Hech narsa, Facebook ismga qaramaydi"}, {"id": "b", "text": "Cheklov tezroq yechiladi"}, {"id": "c", "text": "Facebook profil ismini o'zi to'g'rilab qo'yadi"}, {"id": "d", "text": "Tasdiqlanmaydi, cheklov qoladi, hatto akkaunt bloklanishi mumkin"}], "explanation": "Ustozning cheklovi 2 daqiqada yechildi, chunki hujjatdagi ism profil ismiga mos edi. Ma'lumot noto'g'ri yoki soxta bo'lsa, tasdiqlanmaydi va akkaunt bloklanishi mumkin.", "correct_option_id": "d"}, {"id": "q9", "prompt": "Cheklov sahifasida «до 12 июля» kabi sana yozilgan edi. Bu nimani bildiradi?", "options": [{"id": "a", "text": "Shu sanagacha tekshiruv so'rash mumkin. Muddat o'tsa, cheklov doimiy bo'lib qolishi mumkin"}, {"id": "b", "text": "Cheklov shu sanada o'zi yechiladi"}, {"id": "c", "text": "BM shu sanada o'chiriladi"}, {"id": "d", "text": "Reklama to'lovi shu sanada yechiladi"}], "explanation": "Tekshiruvni shu sanagacha so'rash kerak. Kechiksangiz, cheklov doimiy bo'lib qolishi mumkin.", "correct_option_id": "a"}, {"id": "q10", "prompt": "Cheklov yechilganini qayerdan bilasiz?", "options": [{"id": "a", "text": "Instagram'ga xabar keladi"}, {"id": "b", "text": "Sahifada «Доступ к размещению рекламы восстановлен» (Reklamaga ruxsat tiklandi) chiqadi va Gmailga «СРОЧНО: Доступ ... восстановлен» xati keladi"}, {"id": "c", "text": "BM nomi o'zgaradi"}, {"id": "d", "text": "Hech qanday belgi bo'lmaydi"}], "explanation": "Videoda taxminan 2 daqiqada «Доступ к размещению рекламы восстановлен (Advertising access restored)» chiqdi, Gmailga esa «СРОЧНО: Доступ бизнес-аккаунта к рекламным функциям восстановлен» xati keldi.", "correct_option_id": "b"}]$json$::jsonb where id = '3-2';
update public.tests set questions = $json$[{"id": "q1", "prompt": "BMga iloji boricha ko'p haqiqiy ma'lumot kiritish nima uchun kerak?", "options": [{"id": "a", "text": "Facebook ishonchi (trust) oshadi, u biznes haqiqiy ekanini ko'radi"}, {"id": "b", "text": "BM chiroyliroq ko'rinadi"}, {"id": "c", "text": "Reklama bepul bo'lib qoladi"}, {"id": "d", "text": "Hech narsa o'zgarmaydi, bu shart emas"}], "explanation": "Ustoz aytganidek: qancha ko'p haqiqiy ma'lumot kiritsangiz, Facebook sizni haqiqiy, qonuniy ishlayotgan biznes deb shuncha ko'proq ishonadi.", "correct_option_id": "a"}, {"id": "q2", "prompt": "BM haqidagi ma'lumotlar (nom, manzil, telefon, sayt) qaysi bo'limda to'ldiriladi?", "options": [{"id": "a", "text": "Настройки компании (Business settings) > «Информация о компании» (Kompaniya haqida ma'lumot)"}, {"id": "b", "text": "Ads Manager > «Отчеты (Reports)»"}, {"id": "c", "text": "Facebook sahifaning «О нас (About)» bo'limida"}, {"id": "d", "text": "Настройки компании (Business settings) > «Партнеры (Partners)»"}], "explanation": "Kompaniya sozlamalaridagi chap menyuning pastida «Информация о компании (Business info)» bo'limi bor. «Сведения о компании (Business details)» blokida «Редактировать (Edit)» bosiladi.", "correct_option_id": "a"}, {"id": "q3", "prompt": "«Моя информация (My info)» blokida emailingiz tasdiqlanmagan deb sariq ogohlantirish turibdi. Nima qilasiz?", "options": [{"id": "a", "text": "«Отправить письмо повторно (Resend email)» ni bosib, Gmaildagi «Confirm your business email» xatida «Confirm now» ni bosaman"}, {"id": "b", "text": "Hech narsa, admin bo'lsam email shart emas"}, {"id": "c", "text": "BMni o'chirib qaytadan yarataman"}, {"id": "d", "text": "Emailni o'chirib, telefon raqam yozaman"}], "explanation": "Admin bo'lib kirgan bo'lsangiz ham email tasdiqlangan bo'lishi kerak. Xat ko'pincha Gmailning Social bo'limiga tushadi.", "correct_option_id": "a"}, {"id": "q4", "prompt": "«Юридическое название компании» (Yuridik nom) maydoniga nima yoziladi?", "options": [{"id": "a", "text": "Instagram username'ingiz"}, {"id": "b", "text": "Ism-familiyangiz"}, {"id": "c", "text": "Davlat ro'yxatidan o'tgan guvohnomadagi rasmiy nom. Guvohnoma bo'lmasa, o'ylab topilgan biznes nomi"}, {"id": "d", "text": "Istalgan tasodifiy so'z"}], "explanation": "Ustoz: guvohnomangiz bo'lsa, undagi nomni yozing. Bo'lmasa, masalan marketing agentligi uchun o'ylab topilgan nom (ROAS AGENCY) yoziladi.", "correct_option_id": "c"}, {"id": "q5", "prompt": "Kompaniya ma'lumotlarida «Номер налогоплательщика (Tax ID)» degan maydon bor. U nima?", "options": [{"id": "a", "text": "Telefon raqami"}, {"id": "b", "text": "Pasport seriyasi"}, {"id": "c", "text": "Bank karta raqami"}, {"id": "d", "text": "STIR (soliq to'lovchining raqami), 9 xonali. Ixtiyoriy, lekin bo'lsa kiritgan yaxshi"}], "explanation": "Bu STIR (ИНН). Odatda saytingizning pastki qismida yoki rasmiy hujjatlarda yozilgan bo'ladi.", "correct_option_id": "d"}, {"id": "q6", "prompt": "Ustoz BM nomini «ROAS AGENCY» qilib saqlamoqchi bo'ldi va «Недопустимое название компании (Invalid business name)» xatosi chiqdi. Nega?", "options": [{"id": "a", "text": "Nomda raqam yo'q edi"}, {"id": "b", "text": "Bunday nomli BM allaqachon bor edi"}, {"id": "c", "text": "Nom juda qisqa edi"}, {"id": "d", "text": "Nom faqat katta harflarda yozilgan edi. «Roas Agency» qilib yozilgach qabul qilindi"}], "explanation": "Facebook kompaniya nomini faqat katta harflarda qabul qilmadi. Nom real biznes nomiga mos va oddiy yozilishda bo'lishi kerak.", "correct_option_id": "d"}, {"id": "q7", "prompt": "Nega yuridik nom va BM nomi bir-biriga mos bo'lishi kerak?", "options": [{"id": "a", "text": "Aks holda reklama qimmatlashadi"}, {"id": "b", "text": "Bunga hech qanday sabab yo'q"}, {"id": "c", "text": "Aks holda sahifa o'chib ketadi"}, {"id": "d", "text": "Keyinchalik BMni tasdiqlash (verifikatsiya) paytida hujjat so'raladi va nomlar mos kelishi kerak"}], "explanation": "Masalan yuridik nom ROAS AGENCY bo'lsa-yu, BM nomi butunlay boshqa bo'lsa, tasdiqlash paytida muammo chiqadi.", "correct_option_id": "d"}, {"id": "q8", "prompt": "Ikki bosqichli autentifikatsiya (Двухфакторная аутентификация (Two-factor authentication)) sozlamasi qayerda?", "options": [{"id": "a", "text": "«Биллинг и платежи (Billing & payments)» bo'limida"}, {"id": "b", "text": "«Партнеры (Partners)» bo'limida"}, {"id": "c", "text": "Facebook sahifaning «Настройки (Settings)» bo'limida"}, {"id": "d", "text": "Настройки компании (Business settings) > «Центр безопасности» (Xavfsizlik markazi)"}], "explanation": "«Центр безопасности (Security Center)» da «Кто должен включить двухфакторную аутентификацию? (Who must turn on two-factor authentication?)» savoli bor: Никто / Только админы / Все (No one / Only admins / Everyone).", "correct_option_id": "d"}, {"id": "q9", "prompt": "Ikki bosqichli autentifikatsiyani «Все» (Hamma) uchun majburiy qilsangiz nima bo'ladi?", "options": [{"id": "a", "text": "Reklama to'xtab qoladi"}, {"id": "b", "text": "Hamma odamlar BMdan o'chib ketadi"}, {"id": "c", "text": "Hech narsa o'zgarmaydi"}, {"id": "d", "text": "2FA yoqmagan odam BMga kira olmaydi. Login-parol o'g'irlansa ham BM va reklama akkaunti himoyalangan bo'ladi"}], "explanation": "Ustoz misol keltirdi: adminingizning paroli o'g'irlansa, 2FA bo'lmasa begona odam BMga kirib, pulingizdan reklama yurgizishi mumkin.", "correct_option_id": "d"}, {"id": "q10", "prompt": "«Центр безопасности (Security Center)» da «Добавить администратора (Add admin)» bloki «Вы единственный администратор (You're the only admin)» deydi. Bu nimani tavsiya qiladi?", "options": [{"id": "a", "text": "Adminlikdan voz kechishni"}, {"id": "b", "text": "Ikkinchi BM ochishni"}, {"id": "c", "text": "Ikkinchi admin qo'shishni: bittasi kira olmay qolsa, ikkinchisi BMni boshqara oladi"}, {"id": "d", "text": "BMni boshqa odamga sotishni"}], "explanation": "Siz yagona admin bo'lsangiz va akkauntingiz bloklansa, BMga kirish yo'qoladi. Ishonchli ikkinchi admin zaxira bo'lib turadi.", "correct_option_id": "c"}]$json$::jsonb where id = '3-3';
update public.tests set questions = $json$[{"id": "q1", "prompt": "BMga yangi odam (admin yoki xodim) qo'shish uchun qayerga kirasiz?", "options": [{"id": "a", "text": "Facebook sahifa > «Настройки (Settings)» > «Роли (Roles)»"}, {"id": "b", "text": "Ads Manager > «Кампании (Campaigns)»"}, {"id": "c", "text": "Настройки компании > Пользователи (Business settings > Users) > «Люди (People)» > ko'k «Пригласить людей (Invite people)» tugmasi"}, {"id": "d", "text": "Настройки компании (Business settings) > «Домены (Domains)»"}], "explanation": "«Люди (People)» jadvalida ism, email, kirish huquqi va status ko'rinadi. O'ng yuqoridagi «Пригласить людей (Invite people)» orqali taklif yuboriladi.", "correct_option_id": "c"}, {"id": "q2", "prompt": "Taklif qilmoqchi bo'lgan odamning qaysi ma'lumoti kerak?", "options": [{"id": "a", "text": "Telefon raqami"}, {"id": "b", "text": "Uning Facebook akkauntiga bog'langan emaili"}, {"id": "c", "text": "Pasport raqami"}, {"id": "d", "text": "Telegram username'i"}], "explanation": "1-qadamda «Введите электронные адреса (Enter email addresses)» maydoniga email yoziladi. Email Facebook akkauntidagi kontakt email bilan bir xil bo'lishi kerak.", "correct_option_id": "b"}, {"id": "q3", "prompt": "Odam o'zining Facebook'dagi kontakt emailini qayerdan ko'radi?", "options": [{"id": "a", "text": "Facebook > Настройки и конфиденциальность > Центр аккаунтов > Личная информация > Контактная информация (Settings & privacy > Accounts Center > Personal details > Contact info)"}, {"id": "b", "text": "Gmail > Настройки"}, {"id": "c", "text": "Instagram > Профиль > Изменить (Profile > Edit)"}, {"id": "d", "text": "Facebook > Сохраненное"}], "explanation": "Ustoz videoda shu yo'lni ko'rsatdi: «Контактная информация (Contact info)» oynasida email va telefon raqam ko'rinadi.", "correct_option_id": "a"}, {"id": "q4", "prompt": "2-qadamdagi «Полный доступ (Full control)» > «Всё (Everything)» > «Управление (Manage)» qanday huquq beradi?", "options": [{"id": "a", "text": "Faqat statistikani ko'rish"}, {"id": "b", "text": "Faqat reklama to'lovini ko'rish"}, {"id": "c", "text": "Faqat post joylash"}, {"id": "d", "text": "Eng yuqori huquq: hamma narsani boshqaradi, odam qo'shadi va o'chiradi, hatto BMni o'chira oladi"}], "explanation": "Shu sababli oynada sariq ogohlantirish bor: biznes akkauntni himoya qilish uchun boshqaruvchilar sonini cheklang.", "correct_option_id": "d"}, {"id": "q5", "prompt": "To'lov (moliya) ma'lumotlariga kirish huquqi qayerda beriladi?", "options": [{"id": "a", "text": "«Базовый доступ (Basic access)» da avtomatik beriladi"}, {"id": "b", "text": "Faqat Ads Manager ichida beriladi"}, {"id": "c", "text": "Bunday huquq yo'q"}, {"id": "d", "text": "«Смотреть расширенные настройки» (Kengaytirilgan sozlamalar) > «Финансы (Finance)»: Не назначать / Просмотр / Управление (Don't assign / View / Manage)"}], "explanation": "«Финансы (Finance)» da uch daraja bor: berilmaydi, faqat ko'rish yoki boshqarish.", "correct_option_id": "d"}, {"id": "q6", "prompt": "Taklif yuborilgandan keyin odam ro'yxatda qanday holatda turadi?", "options": [{"id": "a", "text": "Ro'yxatda umuman ko'rinmaydi"}, {"id": "b", "text": "«Заблокирован (Blocked)»"}, {"id": "c", "text": "Avval «Приглашение отправлено (Invitation sent)» yoki «Неактивный пользователь (Inactive user)», taklifni qabul qilgach «Активный (Active)»"}, {"id": "d", "text": "Darhol «Активный (Active)»"}], "explanation": "Odam emaildagi taklifni qabul qilmaguncha faol bo'lmaydi.", "correct_option_id": "c"}, {"id": "q7", "prompt": "Taklif qilingan odam taklifni qanday qabul qiladi?", "options": [{"id": "a", "text": "Emaildagi «Компания ... пригласила вас...» xatida «Начать (Get started)» > ismini yozadi > kompaniyani tekshiradi > «Принять приглашение (Accept invitation)»"}, {"id": "b", "text": "Hech narsa qilmaydi, o'zi qo'shiladi"}, {"id": "c", "text": "Facebook Messenger'dagi xabarga javob yozadi"}, {"id": "d", "text": "BM ID'sini qo'lda kiritadi"}], "explanation": "Meta Business Suite'da 4 qadamli oyna ochiladi, oxirgisi «Принять приглашение» (Taklifni qabul qilish).", "correct_option_id": "a"}, {"id": "q8", "prompt": "3-qadam «Предоставление доступа» (Kirish berish) da nima qilinadi?", "options": [{"id": "a", "text": "Odamga to'lov kartasi bog'lanadi"}, {"id": "b", "text": "Odamning paroli o'rnatiladi"}, {"id": "c", "text": "BM nomi o'zgartiriladi"}, {"id": "d", "text": "Odamga aniq obyektlar (sahifa, reklama akkaunti va h.k.) va ular bo'yicha ruxsatlar biriktiriladi"}], "explanation": "Hozircha obyekt bo'lmasa, bu qadamni o'tkazib «Пригласить (Invite)» bosiladi. Obyektlarni keyin ham biriktirsa bo'ladi.", "correct_option_id": "d"}, {"id": "q9", "prompt": "Kimga «Полный доступ» (to'liq huquq) berish kerak?", "options": [{"id": "a", "text": "Har bir mijozga"}, {"id": "b", "text": "Hammaga, qulay bo'lishi uchun"}, {"id": "c", "text": "Har bir xodimga"}, {"id": "d", "text": "Faqat juda ishonchli odamga, chunki admin sizni ham BMdan chiqarib yuborishi mumkin"}], "explanation": "Xodim yoki mijozga odatda cheklangan huquq beriladi, masalan faqat reklama boshqarish yoki moliyani ko'rish.", "correct_option_id": "d"}, {"id": "q10", "prompt": "Taklifni qabul qilishning oxirgi «Проверка (Review)» qadamida odamga nima haqida aytiladi?", "options": [{"id": "a", "text": "Taklifni qabul qilish uchun to'lov kerakligi"}, {"id": "b", "text": "BM 24 soatdan keyin o'chirilishi"}, {"id": "c", "text": "Hech narsa aytilmaydi, faqat tugma bor"}, {"id": "d", "text": "Hamkasblar uning ismi, profil rasmi va ID'sini ko'rishi, harakatlari kompaniyaga ko'rinishi"}], "explanation": "«Проверка (Review)» oynasida ogohlantiriladi: kompaniyadagi hamkasblar sizning ismingiz, profil rasmingiz va ID'ingizni ko'radi, BM ichidagi harakatlaringiz esa kompaniyaga ko'rinadi. Shundan keyin «Принять приглашение (Accept invitation)» bosiladi.", "correct_option_id": "d"}]$json$::jsonb where id = '3-4';
update public.tests set questions = $json$[{"id": "q1", "prompt": "Agentlik mijozning sahifasi va Instagrami bilan «partnyor» sifatida ishlasa, egalik kimda qoladi?", "options": [{"id": "a", "text": "Mijozda qoladi, agentlik faqat ruxsat olgan bo'ladi"}, {"id": "b", "text": "Facebook'ka o'tadi"}, {"id": "c", "text": "Agentlikka o'tadi"}, {"id": "d", "text": "Ikkalasida teng bo'linadi"}], "explanation": "Partnyorlik orqali mijoz o'z obyektlarini o'zida saqlab, agentlikka faqat kerakli ruxsatlarni beradi.", "correct_option_id": "a"}, {"id": "q2", "prompt": "Partnyorlar bo'limi qayerda?", "options": [{"id": "a", "text": "Ads Manager > «Аудитории (Audiences)»"}, {"id": "b", "text": "Настройки компании > Пользователи (Business settings > Users) > «Партнеры (Partners)»"}, {"id": "c", "text": "Настройки компании (Business settings) > «Домены (Domains)»"}, {"id": "d", "text": "Facebook sahifa > «Сообщения (Messages)»"}], "explanation": "Bo'sh holatda «Компания ... не работает ни с какими партнерами» yozuvi va ikkita «Добавить (Add)» tugmasi chiqadi.", "correct_option_id": "b"}, {"id": "q3", "prompt": "Partnyorlar sahifasidagi ikki variantning farqi nima?", "options": [{"id": "a", "text": "1) pullik, 2) bepul"}, {"id": "b", "text": "Ikkalasi bir xil"}, {"id": "c", "text": "1) «...можно поделиться объектами» — o'z obyektingizni boshqaga berasiz; 2) «...можно запросить объекты» — boshqadan obyekt so'raysiz"}, {"id": "d", "text": "1) sahifa uchun, 2) faqat Instagram uchun"}], "explanation": "Mijoz o'z BMsida birinchi variantni ishlatib, agentlikka obyekt beradi.", "correct_option_id": "c"}, {"id": "q4", "prompt": "Mijoz agentlikni partnyor qilib qo'shishi uchun agentlikdan nima so'raydi?", "options": [{"id": "a", "text": "Agentlikning Facebook parolini"}, {"id": "b", "text": "Agentlik sahifasining nomini"}, {"id": "c", "text": "Agentlik BMsining ID raqamini («ID аккаунта Business Manager (Business Manager ID)»)"}, {"id": "d", "text": "Agentlikning bank kartasini"}], "explanation": "Bu ID «Информация о компании (Business info)» sahifasining yuqorisida, BM nomi ostida yozilgan bo'ladi.", "correct_option_id": "c"}, {"id": "q5", "prompt": "Mijoz BMsida partnyor qo'shishda ochilgan «Добавление нового партнера (Add a new partner)» oynasiga nima yoziladi?", "options": [{"id": "a", "text": "Agentlik telefon raqami"}, {"id": "b", "text": "Mijozning o'z BM ID'si"}, {"id": "c", "text": "Agentlik emaili"}, {"id": "d", "text": "«ID компании партнера (Partner business ID)» — agentlik BM ID'si"}], "explanation": "ID kiritilgach «Далее (Next)» bosiladi va obyektlar tanlanadigan oyna ochiladi.", "correct_option_id": "d"}, {"id": "q6", "prompt": "«Назначение объектов и разрешений (Assign assets and permissions)» oynasi qanday tuzilgan?", "options": [{"id": "a", "text": "Faqat odamlar ro'yxati chiqadi"}, {"id": "b", "text": "Chapda obyekt turi, o'rtada obyektning o'zi, o'ngda ruxsatlar (Контент, Сообщения, Реклама, Статистика (Content, Messages, Ads, Insights)...)"}, {"id": "c", "text": "Faqat bitta «Разрешить всё (Allow all)» tugmasi bor"}, {"id": "d", "text": "Faqat to'lov ma'lumotlari so'raladi"}], "explanation": "Masalan: Страницы > Kitchen Shop > Реклама va Статистика yoqiladi, keyin «Сохранить изменения (Save changes)» bosiladi.", "correct_option_id": "b"}, {"id": "q7", "prompt": "Instagram akkauntni partnyorga berishda «Невозможно назначить (Can't assign)» chiqdi. Nima qilish kerak?", "options": [{"id": "a", "text": "Instagramni o'chirib qayta yaratish"}, {"id": "b", "text": "24 soat kutish"}, {"id": "c", "text": "«Войти (Log in)» ni bosib, Instagram akkauntiga login qilish kerak, keyin ruxsatlar beriladi"}, {"id": "d", "text": "Bu imkonsiz, Instagram berilmaydi"}], "explanation": "Facebook Instagramga kirishni so'raydi. Kirgach akkaunt ro'yxatda paydo bo'ladi va ruxsatlar tanlanadi.", "correct_option_id": "c"}, {"id": "q8", "prompt": "Agentlik BMsida mijoz bergan obyektlar qayerda ko'rinadi?", "options": [{"id": "a", "text": "«Объекты, к которым вы предоставили доступ (Assets you've shared)» tabida"}, {"id": "b", "text": "Партнеры > mijoz nomi > «Общие объекты» (Umumiy obyektlar) tabida"}, {"id": "c", "text": "Hech qayerda ko'rinmaydi"}, {"id": "d", "text": "«Центр безопасности (Security Center)» da"}], "explanation": "«Общие объекты (Assets shared with you)» — sizga berilganlar. «Объекты, к которым вы предоставили доступ (Assets you've shared)» — siz boshqaga berganlaringiz.", "correct_option_id": "b"}, {"id": "q9", "prompt": "Agentlik BMsida Аккаунты > Страницы (Accounts > Pages) ro'yxatida sahifa ostida «Принадлежит компании kitchenshop.uz (Owned by kitchenshop.uz)» yozilgan. Bu nima?", "options": [{"id": "a", "text": "Sahifa bloklangan"}, {"id": "b", "text": "Sahifa agentlikka sotilgan"}, {"id": "c", "text": "Sahifaning egasi mijoz (kitchenshop.uz), agentlik unga faqat partnyor sifatida kira oladi"}, {"id": "d", "text": "Sahifa hali tasdiqlanmagan"}], "explanation": "Agentlik bu sahifani o'z xodimlariga «Назначить людей (Assign people)» orqali biriktirib, ular bilan ishlay oladi.", "correct_option_id": "c"}, {"id": "q10", "prompt": "Mijoz sahifasini agentlikning xodimi ishlatishi uchun yana nima qilish kerak?", "options": [{"id": "a", "text": "Xodim mijozdan parol so'raydi"}, {"id": "b", "text": "Agentlik BMsida o'sha sahifani tanlab, «Назначить людей (Assign people)» orqali xodimni biriktirish"}, {"id": "c", "text": "Xodim yangi BM ochadi"}, {"id": "d", "text": "Hech narsa, hamma xodim avtomatik kiradi"}], "explanation": "Sahifa agentlik BMsiga kelgach, unda «Никто не подключен. Добавьте людей (No one is connected. Add people)» yozuvi turadi. Odamlarni alohida biriktirasiz.", "correct_option_id": "b"}]$json$::jsonb where id = '3-5';
update public.tests set questions = $json$[{"id": "q1", "prompt": "BMdagi sahifalar qaysi bo'limda boshqariladi?", "options": [{"id": "a", "text": "Настройки компании (Business settings) > «Партнеры (Partners)»"}, {"id": "b", "text": "Настройки компании (Business settings) > «Биллинг (Billing)»"}, {"id": "c", "text": "Настройки компании > Аккаунты (Business settings > Accounts) > «Страницы (Pages)»"}, {"id": "d", "text": "Facebook > «Сохраненное (Saved)»"}], "explanation": "Chapda sahifalar ro'yxati, o'ngda tanlangan sahifa haqida ma'lumot: ID, ruxsatlar, «Назначить людей (Assign people)».", "correct_option_id": "c"}, {"id": "q2", "prompt": "«Страницы (Pages)» bo'limidagi ko'k «Добавить (Add)» tugmasi qanday 3 ta variantni beradi?", "options": [{"id": "a", "text": "«Купить (Buy)», «Продать (Sell)», «Удалить (Remove)»"}, {"id": "b", "text": "«Лайк (Like)», «Подписаться (Follow)», «Поделиться (Share)»"}, {"id": "c", "text": "«Добавить Страницу (Add a Page)», «Запросить доступ к Странице (Request access to a Page)», «Создание новой Страницы (Create a new Page)»"}, {"id": "d", "text": "Faqat bitta variant bor"}], "explanation": "Birinchisi o'z sahifangiz uchun, ikkinchisi mijoz sahifasi uchun, uchinchisi yangi sahifa ochish uchun.", "correct_option_id": "c"}, {"id": "q3", "prompt": "O'zingiz admin bo'lgan sahifani BMga qo'shmoqchisiz. Qaysi variantni tanlaysiz?", "options": [{"id": "a", "text": "«Запросить доступ к Странице (Request access to a Page)»"}, {"id": "b", "text": "«Добавить Страницу (Add a Page)» — sahifa BMga qo'shiladi va BM uning egasi bo'ladi"}, {"id": "c", "text": "«Пригласить людей (Invite people)»"}, {"id": "d", "text": "«Создание новой Страницы (Create a new Page)»"}], "explanation": "O'zingizning sahifangiz bo'lgani uchun egalikni BMga o'tkazasiz.", "correct_option_id": "b"}, {"id": "q4", "prompt": "Mijozning sahifasi bilan ishlash kerak, lekin egalik mijozda qolishi kerak. Qaysi variant?", "options": [{"id": "a", "text": "«Запросить доступ к Странице» (Sahifaga kirish so'rash)"}, {"id": "b", "text": "Sahifa parolini so'rash"}, {"id": "c", "text": "«Создание новой Страницы (Create a new Page)»"}, {"id": "d", "text": "«Добавить Страницу (Add a Page)»"}], "explanation": "So'rov yuborilgach, sahifa adminlari uni tasdiqlashi kerak. Egalik o'zgarmaydi.", "correct_option_id": "a"}, {"id": "q5", "prompt": "Ustoz o'z sahifasini qo'shganda so'rov darhol tasdiqlandi. Nega?", "options": [{"id": "a", "text": "U pul to'lagan edi"}, {"id": "b", "text": "U shu sahifaning admini edi, shuning uchun so'rov avtomatik tasdiqlandi"}, {"id": "c", "text": "BM tasdiqlangan edi"}, {"id": "d", "text": "Sahifa yangi edi"}], "explanation": "Oynada shunday yozilgan edi: «поскольку вы уже являетесь администратором этой Страницы, ваш запрос был автоматически одобрен».", "correct_option_id": "b"}, {"id": "q6", "prompt": "Mijoz sahifasiga so'rov yuborgandan keyin sahifa ostida qanday yozuv chiqadi?", "options": [{"id": "a", "text": "«Доступ предоставлен навсегда (Access granted permanently)»"}, {"id": "b", "text": "«Страница удалена (Page deleted)»"}, {"id": "c", "text": "«Ваш запрос ожидает одобрения» (So'rovingiz tasdiqni kutmoqda) va «Отменить запрос (Cancel request)» tugmasi"}, {"id": "d", "text": "Hech qanday yozuv chiqmaydi"}], "explanation": "Mijoz tasdiqlamaguncha sahifa bilan ishlay olmaysiz va unga odam biriktira olmaysiz.", "correct_option_id": "c"}, {"id": "q7", "prompt": "«Требуется основная Страница (Primary Page required)» oynasi nimani so'raydi?", "options": [{"id": "a", "text": "Yangi BM ochishni"}, {"id": "b", "text": "Sahifaga reklama to'lashni"}, {"id": "c", "text": "Sahifani o'chirishni"}, {"id": "d", "text": "BMning asosiy (Основная) sahifasini tanlashni, bu boshqa obyektlarga ruxsat so'rash uchun kerak"}], "explanation": "Asosiy sahifani keyin «Информация о компании (Business info)» > nom yonidagi «Редактировать (Edit)» > «Основная Страница (Primary Page)» orqali ham tanlash mumkin.", "correct_option_id": "d"}, {"id": "q8", "prompt": "Mijoz sahifasiga so'rov yuborishda faqat reklama yurgizish va natijani ko'rish kerak. Qaysi ruxsatlarni yoqasiz?", "options": [{"id": "a", "text": "«Всё (кроме ответственных действий) (Everything except sensitive actions)»"}, {"id": "b", "text": "«Реклама (Ads)» va «Статистика (Insights)»"}, {"id": "c", "text": "Faqat «Доход (Revenue)»"}, {"id": "d", "text": "Faqat «Контент (Content)»"}], "explanation": "Videoda ustoz aynan shu ikkitasini yoqdi. Kerakdan ortiq huquq so'rash shart emas.", "correct_option_id": "b"}, {"id": "q9", "prompt": "«Создание новой Страницы (Create a new Page)» bosilganda birinchi nima tanlanadi?", "options": [{"id": "a", "text": "Instagram akkaunt"}, {"id": "b", "text": "Reklama byudjeti"}, {"id": "c", "text": "To'lov usuli"}, {"id": "d", "text": "Sahifa kategoriyasi (masalan «Местная компания или место (Local business or place)», «Марка или продукт (Brand or product)»)"}], "explanation": "Kategoriyadan keyin «Название Страницы (Page name)» yoziladi va «Создать Страницу (Create Page)» bosiladi.", "correct_option_id": "d"}, {"id": "q10", "prompt": "«Добавить Страницу (Add a Page)» va «Запросить доступ к Странице (Request access to a Page)» ning asosiy farqi nima?", "options": [{"id": "a", "text": "Birinchisi pullik"}, {"id": "b", "text": "Farqi yo'q"}, {"id": "c", "text": "Ikkinchisi faqat Instagram uchun"}, {"id": "d", "text": "Birinchisida sahifaning egasi BM bo'ladi, ikkinchisida egalik avvalgi egasida qoladi"}], "explanation": "Shuning uchun mijoz sahifasini hech qachon «Добавить (Add)» qilmaysiz, faqat ruxsat so'raysiz.", "correct_option_id": "d"}]$json$::jsonb where id = '3-6';
update public.tests set questions = $json$[{"id": "q1", "prompt": "Reklama akkauntlari BMning qaysi bo'limida yaratiladi?", "options": [{"id": "a", "text": "Facebook sahifa > «Продвигать (Promote)»"}, {"id": "b", "text": "Instagram > «Профессиональная панель (Professional dashboard)»"}, {"id": "c", "text": "Настройки компании (Business settings) > «Люди (People)»"}, {"id": "d", "text": "Настройки компании > Аккаунты (Business settings > Accounts) > «Рекламные аккаунты (Ad accounts)» > «Добавить (Add)»"}], "explanation": "Bo'sh holatda «У компании ... пока нет рекламных аккаунтов» yozuvi va «Добавить (Add)» tugmasi chiqadi.", "correct_option_id": "d"}, {"id": "q2", "prompt": "«Добавить рекламный аккаунт» (mavjud akkauntni qo'shish) tanlansa nima bo'ladi?", "options": [{"id": "a", "text": "Akkauntga faqat vaqtincha ruxsat olinadi"}, {"id": "b", "text": "Akkaunt BMga ko'chadi va BM uning egasi bo'ladi. Buni qaytarib bo'lmaydi"}, {"id": "c", "text": "Akkaunt o'chiriladi"}, {"id": "d", "text": "Akkaunt nusxasi yaratiladi"}], "explanation": "Mijoz akkaunti uchun «Запросить доступ к рекламному аккаунту (Request access to an ad account)» tanlanadi, shunda egalik mijozda qoladi.", "correct_option_id": "b"}, {"id": "q3", "prompt": "Yangi reklama akkaunt yaratishda qaysi 3 ta maydon to'ldiriladi?", "options": [{"id": "a", "text": "Email, parol, telefon"}, {"id": "b", "text": "Akkaunt nomi, vaqt mintaqasi (Часовой пояс (Time zone)) va valyuta"}, {"id": "c", "text": "Sahifa nomi, kategoriya, logotip"}, {"id": "d", "text": "Karta raqami, CVV, muddati"}], "explanation": "To'lov ma'lumotlari keyin, akkaunt yaratilgandan so'ng kiritiladi. Bu haqda «Платежная информация перемещена (Payment info has moved)» xabari ham bor.", "correct_option_id": "b"}, {"id": "q4", "prompt": "Toshkent vaqti uchun vaqt mintaqasida qaysi variant tanlanadi?", "options": [{"id": "a", "text": "(GMT+00:00) UTC"}, {"id": "b", "text": "(GMT+05:00) Asia/Karachi yoki Asia/Tashkent, ya'ni +5"}, {"id": "c", "text": "(GMT+03:00) Europe/Moscow"}, {"id": "d", "text": "(GMT-08:00) America/Los_Angeles, standart holicha"}], "explanation": "Standart holatda Los-Anjeles turadi, uni +5 ga o'zgartirish kerak. Aks holda statistika vaqtlari noto'g'ri chiqadi.", "correct_option_id": "b"}, {"id": "q5", "prompt": "«Как будет использоваться этот рекламный аккаунт? (This ad account will be used for)» savoliga javob nimaga ta'sir qiladi?", "options": [{"id": "a", "text": "Reklamadagi «Почему я вижу эту рекламу? (Why am I seeing this ad?)» oynasida qaysi kompaniya nomi chiqishiga"}, {"id": "b", "text": "Reklama narxiga"}, {"id": "c", "text": "Akkaunt valyutasiga"}, {"id": "d", "text": "Hech narsaga ta'sir qilmaydi"}], "explanation": "O'z biznesingiz uchun «Моя компания (My business)», mijoz uchun esa «Другой компании или клиента (Another business or client)» tanlanadi.", "correct_option_id": "a"}, {"id": "q6", "prompt": "To'lov ma'lumotlarida mamlakat, valyuta va vaqt mintaqasi haqida qanday ogohlantirish bor?", "options": [{"id": "a", "text": "Ular faqat statistika uchun"}, {"id": "b", "text": "Ularni har oy o'zgartirish kerak"}, {"id": "c", "text": "Ular avtomatik to'g'rilanadi"}, {"id": "d", "text": "Ularni keyin o'zgartirib bo'lmaydi, shuning uchun darhol to'g'ri tanlash kerak"}], "explanation": "Videoda O'zbekiston, AQSh dollari va GMT+05:00 tanlandi.", "correct_option_id": "d"}, {"id": "q7", "prompt": "Soliq ma'lumotiga STIR kiritilmasa nima bo'ladi?", "options": [{"id": "a", "text": "Reklama bepul bo'ladi"}, {"id": "b", "text": "Hech narsa bo'lmaydi"}, {"id": "c", "text": "Facebook har bir to'lov ustiga 12% QQS qo'shib yechadi"}, {"id": "d", "text": "Reklama akkaunt bloklanadi"}], "explanation": "STIR kiritilib «Я юридическое лицо, зарегистрированное в Узбекистане (I'm a business registered in Uzbekistan)» belgilansa, Facebook 12% olmaydi. QQSni O'zbekistonda o'zingiz to'laysiz.", "correct_option_id": "c"}, {"id": "q8", "prompt": "Reklama akkauntiga to'lov usuli sifatida nimalarni qo'shish mumkin?", "options": [{"id": "a", "text": "Faqat naqd pul"}, {"id": "b", "text": "Faqat Click yoki Payme"}, {"id": "c", "text": "Faqat bank o'tkazmasi"}, {"id": "d", "text": "Debet yoki kredit karta (Visa, Mastercard...) yoki PayPal"}], "explanation": "Karta uchun karta egasining ismi, karta raqami, ММ/ГГ va CVV kiritiladi.", "correct_option_id": "d"}, {"id": "q9", "prompt": "«Биллинг и платежи (Billing & payments)» sahifasida «Порог оплаты: $2,00 (Payment threshold: $2.00)» yozilgan. Bu nimani bildiradi?", "options": [{"id": "a", "text": "Sarf 2 dollarga yetganda kartadan pul yechiladi. Yoki oylik hisob sanasida, qaysi biri oldin bo'lsa"}, {"id": "b", "text": "Kuniga faqat 2 dollar sarflash mumkin"}, {"id": "c", "text": "Akkauntda 2 dollar qarz bor"}, {"id": "d", "text": "Har bir reklama 2 dollar turadi"}], "explanation": "Yangi akkauntlarda bu chegara past bo'ladi va Meta keyin uni o'zi oshirib boradi.", "correct_option_id": "a"}, {"id": "q10", "prompt": "«Лимит затрат для аккаунта» (Akkaunt xarajat limiti) nima uchun kerak?", "options": [{"id": "a", "text": "Reklamani tezlashtiradi"}, {"id": "b", "text": "Umumiy sarfga chegara qo'yadi: shu summaga yetganda reklama to'xtaydi"}, {"id": "c", "text": "Kunlik sarfni oshiradi"}, {"id": "d", "text": "Kartadagi pulni bloklaydi"}], "explanation": "Videoda $1000 limit qo'yildi. Bundan tashqari Meta yangi akkauntga o'zi kunlik limit (masalan $50) qo'yadi.", "correct_option_id": "b"}]$json$::jsonb where id = '3-7';
update public.tests set questions = $json$[{"id": "q1", "prompt": "BMdagi Instagram akkauntlar qaysi bo'limda?", "options": [{"id": "a", "text": "Facebook sahifa > «Настройки (Settings)»"}, {"id": "b", "text": "Настройки компании > Аккаунты (Business settings > Accounts) > «Аккаунты Instagram (Instagram accounts)»"}, {"id": "c", "text": "Настройки компании (Business settings) > «Партнеры (Partners)»"}, {"id": "d", "text": "Настройки компании (Business settings) > «Домены (Domains)»"}], "explanation": "Ro'yxatda Instagram akkaunt, uning egasi (Владелец) va berilgan ruxsatlar ko'rinadi.", "correct_option_id": "b"}, {"id": "q2", "prompt": "O'z Instagramingizni BMga qo'shish qaysi tugmadan boshlanadi?", "options": [{"id": "a", "text": "«Пригласить людей (Invite people)»"}, {"id": "b", "text": "«Запросить проверку (Request review)»"}, {"id": "c", "text": "«Создать компанию (Create a business account)»"}, {"id": "d", "text": "Ko'k «Добавить (Add)» tugmasi > «Добавление аккаунта Instagram (Add an Instagram account)» oynasi"}], "explanation": "Oynada Instagram ulanganda nimalarni boshqarish mumkinligi yozilgan, pastda «Подключить аккаунт Instagram (Connect Instagram account)» tugmasi bor.", "correct_option_id": "d"}, {"id": "q3", "prompt": "BMga qanday Instagram akkaunt qo'shish mumkin?", "options": [{"id": "a", "text": "Faqat ko'k belgili akkauntlar"}, {"id": "b", "text": "Faqat shaxsiy akkaunt"}, {"id": "c", "text": "Faqat 10 000 dan ko'p obunachisi borlar"}, {"id": "d", "text": "Faqat professional (biznes yoki autor) akkaunt. Shaxsiy akkaunt qo'shilsa, u professionalga o'zgartiriladi"}], "explanation": "Oynadagi sariq ogohlantirish aynan shu haqida.", "correct_option_id": "d"}, {"id": "q4", "prompt": "Instagram BMga ulangach, BMdagi odamlar va partnyorlar nimalarni boshqara oladi (ruxsatga qarab)?", "options": [{"id": "a", "text": "Hech narsani, faqat ko'radi"}, {"id": "b", "text": "Faqat profil rasmini"}, {"id": "c", "text": "Faqat parolni"}, {"id": "d", "text": "Kontent, xabarlar, e'lonlar (reklama), izohlar va statistika"}], "explanation": "Oynada sanab o'tilgan: Контент, Сообщения, Объявления, Комментарии, Статистика (Content, Messages, Ads, Comments, Insights).", "correct_option_id": "d"}, {"id": "q5", "prompt": "«Подключить аккаунт Instagram (Connect Instagram account)» bosilgandan keyin nima bo'ladi?", "options": [{"id": "a", "text": "Yangi Instagram akkaunt yaratiladi"}, {"id": "b", "text": "Akkaunt avtomatik ulanadi"}, {"id": "c", "text": "Instagram login oynasi ochiladi, akkauntga kirib ulanishni tasdiqlaysiz"}, {"id": "d", "text": "Instagramga SMS keladi va tamom"}], "explanation": "Instagramga kirmasdan uni BMga ulab bo'lmaydi.", "correct_option_id": "c"}, {"id": "q6", "prompt": "Ro'yxatda @kitchenshop.uz ostida «Владелец: kitchenshop.uz (Owned by: kitchenshop.uz)» yozilgan. Agentlik BMsi uchun bu nimani bildiradi?", "options": [{"id": "a", "text": "Instagram hali ulanmagan"}, {"id": "b", "text": "Instagramning egasi mijoz BMsi, agentlik unga partnyor sifatida kira oladi"}, {"id": "c", "text": "Instagram bloklangan"}, {"id": "d", "text": "Instagram agentlikka tegishli"}], "explanation": "5-darsda mijoz bu Instagramni partnyor orqali agentlikka bergan edi.", "correct_option_id": "b"}, {"id": "q7", "prompt": "Instagram yonidagi «Предоставленные разрешения: Статистика, Реклама, Сообщения, Контент (Permissions: Insights, Ads, Messages, Content)» nima?", "options": [{"id": "a", "text": "Facebook qo'ygan cheklovlar"}, {"id": "b", "text": "Instagram obunachilari"}, {"id": "c", "text": "Mijoz agentlikka shu Instagram bo'yicha bergan ruxsatlar ro'yxati"}, {"id": "d", "text": "Instagramdagi postlar soni"}], "explanation": "Agentlik faqat shu ro'yxatdagi ishlarni qila oladi.", "correct_option_id": "c"}, {"id": "q8", "prompt": "Agentlik xodimiga shu Instagram bilan ishlash uchun nima qilinadi?", "options": [{"id": "a", "text": "Instagramni tanlab, «Назначить людей (Assign people)» orqali xodimni biriktirish"}, {"id": "b", "text": "Xodim yangi Instagram ochadi"}, {"id": "c", "text": "Hech narsa, hamma avtomatik kiradi"}, {"id": "d", "text": "Xodimga Instagram parolini berish"}], "explanation": "«Люди (People)» tabida hozircha hech kim yo'q bo'lsa, «Назначить людей (Assign people)» orqali qo'shiladi.", "correct_option_id": "a"}, {"id": "q9", "prompt": "Mijoz o'z Instagramini partnyorga berayotganda «Невозможно назначить (Can't assign)» chiqdi. Sababi nima?", "options": [{"id": "a", "text": "Instagram shaxsiy akkaunt"}, {"id": "b", "text": "Partnyor ID xato"}, {"id": "c", "text": "Instagram juda yangi"}, {"id": "d", "text": "Avval «Войти (Log in)» orqali Instagram akkauntiga kirish kerak"}], "explanation": "Bu 5-darsda ko'rsatilgan: Instagramga kirilgach, u ro'yxatda paydo bo'ladi va ruxsat beriladi.", "correct_option_id": "d"}, {"id": "q10", "prompt": "Instagramni BMga ulashning asosiy foydasi nima?", "options": [{"id": "a", "text": "Instagram ko'k belgi oladi"}, {"id": "b", "text": "Instagram reklamasi, xabarlar va statistikani bitta BMdan boshqarish va xodimlarga xavfsiz ruxsat berish"}, {"id": "c", "text": "Postlar avtomatik joylanadi"}, {"id": "d", "text": "Obunachilar soni avtomatik ko'payadi"}], "explanation": "Shunda xodimlarga Instagram parolini bermasdan, faqat kerakli ruxsatlarni berasiz.", "correct_option_id": "b"}]$json$::jsonb where id = '3-8';
update public.tests set questions = $json$[{"id": "q1", "prompt": "Domenlarni tasdiqlash bo'limi qayerda?", "options": [{"id": "a", "text": "Ads Manager > «Кампании (Campaigns)»"}, {"id": "b", "text": "Facebook sahifa > «О нас (About)»"}, {"id": "c", "text": "Настройки компании (Business settings) > «Безопасность бренда» (Brend xavfsizligi) > «Домены (Domains)»"}, {"id": "d", "text": "Настройки компании (Business settings) > «Партнеры (Partners)»"}], "explanation": "Bo'sh holatda «У компании ... ещё нет доменов» yozuvi va «Добавить (Add)» tugmasi chiqadi.", "correct_option_id": "c"}, {"id": "q2", "prompt": "Domenni tasdiqlash uchun sizda nima bo'lishi kerak?", "options": [{"id": "a", "text": "Hech narsa kerak emas"}, {"id": "b", "text": "Faqat Instagram akkaunt"}, {"id": "c", "text": "Faqat Facebook sahifa"}, {"id": "d", "text": "O'z saytingiz (domeningiz) va uning kodiga yoki sozlamalariga kirish huquqi"}], "explanation": "Videoda Tilda'dagi planet-shop.uz va WordPress'dagi roas.uz saytlari ko'rsatildi.", "correct_option_id": "d"}, {"id": "q3", "prompt": "«Добавить домен (Add domain)» oynasiga domen qanday yoziladi?", "options": [{"id": "a", "text": "@planet-shop.uz"}, {"id": "b", "text": "Faqat domen nomi, masalan planet-shop.uz (http://, https:// va www yozilmaydi)"}, {"id": "c", "text": "planet-shop"}, {"id": "d", "text": "https://www.planet-shop.uz/"}], "explanation": "Oynada ham shunday ko'rsatma bor: faqat domen nomini kiriting.", "correct_option_id": "b"}, {"id": "q4", "prompt": "Domen qo'shilgandan keyin uning holati qanday bo'ladi?", "options": [{"id": "a", "text": "«Заблокирован (Blocked)»"}, {"id": "b", "text": "Qizil rangda «Не подтвержден» (Tasdiqlanmagan)"}, {"id": "c", "text": "«Удалён (Removed)»"}, {"id": "d", "text": "Darhol yashil «Подтвержден (Verified)»"}], "explanation": "Tasdiqlash usullaridan birini bajarmaguncha domen tasdiqlanmagan holda turadi.", "correct_option_id": "b"}, {"id": "q5", "prompt": "Domenni tasdiqlashning qaysi 3 ta usuli bor?", "options": [{"id": "a", "text": "SMS, email, qo'ng'iroq"}, {"id": "b", "text": "Pasport, guvohnoma, ID karta"}, {"id": "c", "text": "Like, izoh, repost"}, {"id": "d", "text": "Meta-tegni HTML kodga qo'shish, HTML faylni saytning asosiy papkasiga yuklash, DNS'ga TXT yozuv qo'shish"}], "explanation": "«Выберите один вариант (Select one option)» ro'yxatida shu uchtasi bor. Videoda meta-teg usuli ko'rsatildi.", "correct_option_id": "d"}, {"id": "q6", "prompt": "Meta-teg saytning qaysi joyiga qo'yiladi?", "options": [{"id": "a", "text": "Telegram kanalga"}, {"id": "b", "text": "Sahifaning eng pastidagi matnga"}, {"id": "c", "text": "Rasm nomiga"}, {"id": "d", "text": "Bosh sahifa HTML kodining <head>...</head> qismiga"}], "explanation": "Teg shunday ko'rinadi: <meta name=\"facebook-domain-verification\" content=\"...\">. Uni nusxalab, <head> ichiga qo'yasiz.", "correct_option_id": "d"}, {"id": "q7", "prompt": "Tilda saytida meta-teg qayerga qo'yiladi?", "options": [{"id": "a", "text": "Tilda'da buni qilib bo'lmaydi"}, {"id": "b", "text": "Настройки сайта > «Еще (More)» > «HTML-код для вставки внутрь HEAD», keyin barcha sahifalarni qayta nashr qilish"}, {"id": "c", "text": "Sayt nomiga"}, {"id": "d", "text": "Har bir rasmga alt-matn sifatida"}], "explanation": "Saqlagach «Опубликовать все страницы» qilish shart, aks holda o'zgarish saytda ko'rinmaydi.", "correct_option_id": "b"}, {"id": "q8", "prompt": "WordPress saytida videoda qanday qo'yildi?", "options": [{"id": "a", "text": "Mavzu (theme) o'chirildi"}, {"id": "b", "text": "WPCode plaginining «Header & Footer» bo'limidagi «Header» qismiga qo'yib, «Save Changes» bosildi"}, {"id": "c", "text": "Yangi post sifatida joylandi"}, {"id": "d", "text": "Sayt sarlavhasiga yozildi"}], "explanation": "Header qismidagi kod har bir sahifaning <head> qismiga qo'shiladi.", "correct_option_id": "b"}, {"id": "q9", "prompt": "Teg qo'yildi, lekin «Подтвердить домен (Verify domain)» bosilganda darhol tasdiqlanmadi. Nima qilish kerak?", "options": [{"id": "a", "text": "Sayt nashr qilinganini tekshirib, kutish kerak: Facebook kodni topishi 72 soatgacha vaqt olishi mumkin"}, {"id": "b", "text": "Boshqa BMga o'tish"}, {"id": "c", "text": "BMni o'chirish"}, {"id": "d", "text": "Domenni o'chirib yangisini sotib olish"}], "explanation": "Oynadagi eslatmada shunday yozilgan. Saytni ochib, manba kodida teg borligini ham tekshirish mumkin.", "correct_option_id": "a"}, {"id": "q10", "prompt": "Domen tasdiqlanganini qanday bilasiz?", "options": [{"id": "a", "text": "Sayt nomi o'zgaradi"}, {"id": "b", "text": "Hech qanday belgi bo'lmaydi"}, {"id": "c", "text": "«Домен ... подтвержден! (Domain ... verified!)» xabari chiqadi va holat yashil «Подтвержден (Verified)» bo'ladi"}, {"id": "d", "text": "Gmailga to'lov cheki keladi"}], "explanation": "Shundan keyin domenga partnyorlar va obyektlarni biriktirish mumkin bo'ladi.", "correct_option_id": "c"}]$json$::jsonb where id = '3-9';
insert into public.tests(id, section, section_order, lesson_order, title, questions, published) values ('3-1r', '3. Biznes menejer', 3, 1, '1. BM akkaunt yaratish', $json$[{"id": "q1", "image": "images/3-1/q1.jpg", "prompt": "Rasmda business.facebook.com/select sahifasi ochiq. Yangi BM yaratish uchun qaysi joyni bosasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "keep_order": true, "explanation": "A: ko'k «Создать компанию» (Kompaniya yaratish) tugmasi. B: mavjud BM kartochkasi, C: qidiruv, D: sahifa pastidagi havolalar.", "correct_option_id": "a"}, {"id": "q2", "image": "images/3-1/q2.jpg", "prompt": "BM yaratish oynasi ochildi. Kompaniya nomi (masalan «Murad Buildings») qaysi maydonga yoziladi?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "keep_order": true, "explanation": "B: «Название компании и аккаунта (Business and account name)». A: «Ваше имя» (ismingiz), C: «Ваш рабочий электронный адрес» (email), D: «Отправить (Submit)» tugmasi.", "correct_option_id": "b"}, {"id": "q3", "image": "images/3-1/q3.jpg", "prompt": "BM yaratildi, endi emailni tasdiqlash kerak. Gmailda Primary bo'limi ochiq, lekin «Confirm your business email» xati ko'rinmayapti. Qayerni bosasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "keep_order": true, "explanation": "C: Social bo'limi. Videoda Facebook xati aynan shu yerga tushgan edi (yonida «1 new» yozuvi ham bor). A: Primary, B: Promotions, D: qidiruv.", "correct_option_id": "c"}, {"id": "q4", "image": "images/3-1/q4.jpg", "prompt": "Ustoz uchinchi BMni yaratgandan keyin qizil ramkadagi «Создать компанию (Create a business account)» tugmasi rasmdagidek xira bo'lib qoldi. Bu nimani bildiradi?", "options": [{"id": "a", "text": "Facebook akkaunt hali yangi, ishonch past, shuning uchun hozircha yana BM ochishga ruxsat yo'q"}, {"id": "b", "text": "Internet sekin ishlayapti"}, {"id": "c", "text": "Barcha BMlar o'chirib yuborildi"}, {"id": "d", "text": "Tugma faqat telefonda ishlaydi"}], "explanation": "Ustozning aytishicha, akkaunt yangi bo'lgani uchun Facebook ko'proq BM ochishga ruxsat bermadi. Reklama yurgizib, ishonch oshgach tugma yana ochiladi.", "correct_option_id": "a"}, {"id": "q5", "image": "images/3-1/q5.jpg", "prompt": "Chap yuqoridagi ro'yxat ochildi. Qaysi qator sizning SHAXSIY Facebook akkauntingiz (BM emas)?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "keep_order": true, "explanation": "C: «Ваш аккаунт (Your account)» ostidagi qator shaxsiy akkaunt. B: Murad Buildings, bu BM. A: qidiruv, D: «Создать бизнес-аккаунт» (yangi BM yaratish). Reklamani shaxsiy akkauntdan emas, BM orqali yurgizamiz.", "correct_option_id": "c"}, {"id": "q6", "image": "images/3-1/q6.jpg", "prompt": "BM yaratildi va rasmdagi oyna chiqdi. Qizil ramkadagi yozuv nimani talab qilyapti?", "correct_option_id": "a", "explanation": "«Подтвердите адрес электронной почты (Confirm your email)»: BMga to'liq kirish uchun emailga kelgan havolani bosib, emailni tasdiqlash kerak. Ustoz Gmail'ning Social bo'limidan «Confirm now» ni bosdi.", "options": [{"id": "a", "text": "Emailga yuborilgan havolani bosib, emailni tasdiqlash"}, {"id": "b", "text": "Telefon raqamini kiritish"}, {"id": "c", "text": "Pasport rasmini yuklash"}, {"id": "d", "text": "BMni qaytadan yaratish"}]}, {"id": "q7", "image": "images/3-1/q7.jpg", "prompt": "Email tasdiqlangach «Люди (People)» bo'limi ochildi. BM egasining kirish darajasi (eng yuqori huquq) qayerda ko'rsatilgan?", "correct_option_id": "b", "explanation": "B: «Полный доступ — Всё» (to'liq kirish). A: «Активный (Active)» — statusi faol ekanligi, C: «Пригласить людей (Invite people)» — yangi odam taklif qilish, D: «Сессия» — oxirgi kirgan sana.", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "keep_order": true}, {"id": "q8", "image": "images/3-1/q8.jpg", "prompt": "BMning «Главная (Home)» sahifasi ochiq. Reklama yaratish uchun qaysi bo'limga o'tasiz?", "correct_option_id": "a", "explanation": "A: Ads Manager — reklama kampaniyalari shu yerda yaratiladi. B: «Отчеты по рекламе (Ads reporting)» — reklama hisobotlari, C: Events Manager — piksel va hodisalar, D: «Перейти в настройки компании» — BM sozlamalari.", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "keep_order": true}]$json$::jsonb, true) on conflict (id) do update set title = excluded.title, questions = excluded.questions, published = true;
insert into public.tests(id, section, section_order, lesson_order, title, questions, published) values ('3-2r', '3. Biznes menejer', 3, 2, '2. BM cheklovini yechish', $json$[{"id": "q1", "image": "images/3-2/q1.jpg", "keep_order": true, "prompt": "«Центр поддержки для бизнеса» sahifasi ochiq, BM'ga cheklov tushgan. Cheklov xato qo'yilgan deb hisoblasangiz, qaysi tugmani bosasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "b", "explanation": "B: «Запросить проверку» (tekshiruv so'rash). A: qizil «Аккаунт с ограничениями (Restricted account)» yorlig'i, u faqat cheklov borligini ko'rsatadi. C: «Смотреть аккаунты» boshqa akkauntlaringiz holatini ko'rsatadi. D: «Перейти на главную страницу» BM bosh sahifasiga o'tkazadi."}, {"id": "q2", "image": "images/3-2/q2.jpg", "prompt": "«Запросите проверку» oynasida qizil ramkadagi matnda muddat yozilgan (12 июля 2024). Shu sanagacha tekshiruv so'ralmasa nima bo'ladi?", "options": [{"id": "a", "text": "Akkaunt butunlay o'chiriladi (отключен навсегда)"}, {"id": "b", "text": "Cheklov o'z-o'zidan olib tashlanadi"}, {"id": "c", "text": "Hech narsa o'zgarmaydi"}, {"id": "d", "text": "Faqat Instagram akkaunt o'chadi"}], "correct_option_id": "a", "explanation": "Matnda «После этой даты аккаунт будет отключен навсегда» deyilgan, ya'ni muddat o'tsa akkaunt butunlay o'chiriladi. Shuning uchun cheklov tushsa, tekshiruvni kechiktirmay so'rash kerak."}, {"id": "q3", "image": "images/3-2/q3.jpg", "keep_order": true, "prompt": "«Подтвердите, что это вы» oynasi chiqdi. Avval nimani bosish kerak?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "a", "explanation": "A: «Я не робот (I'm not a robot)» katakchasi (reCAPTCHA). Uni belgilamaguncha B «Продолжить» tugmasi ishlamaydi (xira turibdi). C: «Отмена», D: oynani yopish."}, {"id": "q4", "image": "images/3-2/q4.jpg", "keep_order": true, "prompt": "«Подтвердите номер мобильного телефона» oynasi. Telefon raqamini kiritish uchun qayerni bosasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "a", "explanation": "A: «Добавить новый номер телефона». Shundan keyin mamlakat va raqam kiritiladigan oyna ochiladi. B: «Продолжить», C: «Отмена», D: yopish."}, {"id": "q5", "image": "images/3-2/q5.jpg", "keep_order": true, "prompt": "Mamlakat «Узбекистан (+998)» tanlandi, raqam yozildi. Ustoz videoda kodni WhatsApp orqali oldi. Kodni WhatsApp'ga yuborish uchun qayerni bosasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "c", "explanation": "C: «Отправить через WhatsApp (Send via WhatsApp)». D: «Отправить в SMS» kodni SMS qilib yuboradi. A: mamlakat tanlash (standart holatda AQSh +1 turadi, uni O'zbekistonga almashtirish kerak), B: raqam yoziladigan joy."}, {"id": "q6", "image": "images/3-2/q6.jpg", "keep_order": true, "prompt": "«Введите 6-значный код» oynasi. Bir daqiqa kutdingiz, lekin kod kelmadi. Qayerni bosasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "a", "explanation": "A: «Получить ещё один код» (kodni qayta yuborish). C: 6 xonali kod yoziladigan joy, B: «Продолжить» (kod yozilgandan keyin), D: yopish."}, {"id": "q7", "image": "images/3-2/q7.jpg", "keep_order": true, "prompt": "«Загрузите свое удостоверение личности (Upload your ID)» oynasi. Pasport yoki haydovchilik guvohnomasi rasmini qayerdan yuklaysiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "a", "explanation": "A: «Загрузить изображение (Upload image)». B: «Отмена», C: «Продолжить» (rasm yuklangandan keyin ochiladi), D: «Отказаться» havolasi hujjat nusxasini saqlashdan voz kechish haqida. Hujjatdagi ism Facebook akkauntidagi ismga mos bo'lishi kerak."}, {"id": "q8", "image": "images/3-2/q8.jpg", "prompt": "Hujjat yuklangandan keyin rasmdagi oyna chiqdi. U nimani bildiradi?", "options": [{"id": "a", "text": "So'rov yuborildi, Meta odatda 48 soat ichida javob beradi, shu vaqtgacha cheklov saqlanadi"}, {"id": "b", "text": "Cheklov darhol olib tashlandi"}, {"id": "c", "text": "Hujjat rad etildi, qaytadan yuklash kerak"}, {"id": "d", "text": "BM o'chirib yuborildi"}], "correct_option_id": "a", "explanation": "«Мы ответим вам в течение 48 часов (We'll respond within 48 hours)»: tekshiruv davomida cheklov saqlanib turadi. Videoda javob taxminan 2 daqiqada kelgan, chunki hujjatdagi ism akkauntdagi ismga mos edi."}, {"id": "q9", "image": "images/3-2/q9.jpg", "keep_order": true, "prompt": "Gmail'ga Meta'dan bir nechta xat keldi. Qaysi xat cheklov OLIB TASHLANGANINI bildiradi?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "a", "explanation": "A: «Доступ бизнес-аккаунта к рекламным функциям восстановлен» (tiklandi). B: «Ваш доступ к рекламным функциям ограничен» va C: «Некоторые возможности… ограничены» cheklov tushgani haqidagi xatlar. D: Social bo'limi."}, {"id": "q10", "image": "images/3-2/q10.jpg", "keep_order": true, "prompt": "Tekshiruvdan keyin «Центр поддержки для бизнеса» sahifasi rasmdagidek o'zgardi. Qaysi joy cheklov yechilganini ko'rsatadi?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "a", "explanation": "A: «Доступ к размещению рекламы восстановлен (Advertising access restored)». Avval shu yerda qizil «Аккаунт с ограничениями (Restricted account)» yorlig'i turardi. B: «Перейти на главную страницу», C: reklama qoidalari havolasi, D: «Рекламные аккаунты (0) (Ad accounts (0))»."}]$json$::jsonb, true) on conflict (id) do update set title = excluded.title, questions = excluded.questions, published = true;
insert into public.tests(id, section, section_order, lesson_order, title, questions, published) values ('3-3r', '3. Biznes menejer', 3, 3, '3. BM sozlamalari', $json$[{"id": "q1", "image": "images/3-3/q1.jpg", "prompt": "BM sozlamalarida kompaniya ma'lumotlarini (nomi, manzili, STIR) to'ldirmoqchisiz. Chap menyudan qaysi bo'limni bosasiz?", "correct_option_id": "a", "explanation": "A: «Информация о компании (Business info)». B: «Центр безопасности (Security Center)» — 2FA va adminlar, C: «Пользователи (Users)» — odamlar va partnyorlar, D: «Биллинг и платежи (Billing & payments)» — to'lovlar.", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "keep_order": true}, {"id": "q2", "image": "images/3-3/q2.jpg", "prompt": "«Информация о компании (Business info)» sahifasidagi qizil ramkadagi bo'lim nimani ko'rsatadi?", "correct_option_id": "a", "explanation": "«Лимит создаваемых рекламных аккаунтов: 1» — yangi BMda faqat 1 ta reklama akkaunti yaratish mumkin. Ishonch oshgach limit ko'payadi.", "options": [{"id": "a", "text": "Bu BMda nechta reklama akkaunti yaratish mumkinligini (hozir 1 ta)"}, {"id": "b", "text": "Kunlik reklama byudjetini"}, {"id": "c", "text": "BMdagi adminlar sonini"}, {"id": "d", "text": "Nechta sahifa ulanganini"}]}, {"id": "q3", "image": "images/3-3/q3.jpg", "prompt": "«Моя информация (My info)» bo'limida sariq ogohlantirish chiqib turibdi. Bu nimani bildiradi?", "correct_option_id": "a", "explanation": "Email hali tasdiqlanmagan (Unconfirmed email). Gmail'ga kelgan xatdagi havolani bosib tasdiqlash kerak, aks holda BMning ba'zi funksiyalari ishlamaydi.", "options": [{"id": "a", "text": "Email tasdiqlanmagan — Gmail'dagi xat orqali tasdiqlash kerak"}, {"id": "b", "text": "BM bloklangan"}, {"id": "c", "text": "Parol eskirgan"}, {"id": "d", "text": "Telefon raqami noto'g'ri"}]}, {"id": "q4", "image": "images/3-3/q4.jpg", "prompt": "«Редактирование информации о компании» oynasi. Korxonaning STIR raqami (ИНН) qaysi maydonga yoziladi?", "correct_option_id": "c", "explanation": "C: «Номер налогоплательщика (необязательно)» — soliq to'lovchi raqami, ixtiyoriy. A: «Юридическое название компании (Legal business name)», B: «Страна», D: «Сайт компании».", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "keep_order": true}, {"id": "q5", "image": "images/3-3/q5.jpg", "prompt": "Ustoz «Юридическое название компании (Legal business name)» maydoniga «ROAS AGENCY» deb yozdi. Bu maydonga qanday nom yoziladi?", "correct_option_id": "a", "explanation": "Rasmiy hujjatdagi (guvohnomadagi) nom yoziladi. Hujjat bo'lmasa, biznesingizning haqiqiy nomi. Keyinchalik verifikatsiyada hujjat so'ralgani uchun BM nomi bilan mos bo'lishi kerak.", "options": [{"id": "a", "text": "Rasmiy hujjatdagi (guvohnomadagi) korxona nomi"}, {"id": "b", "text": "Facebook sahifangizning nomi"}, {"id": "c", "text": "Shaxsiy ism-familiyangiz"}, {"id": "d", "text": "Istalgan tasodifiy nom"}]}, {"id": "q6", "image": "images/3-3/q6.jpg", "prompt": "Ustoz STIR raqamini qayerdan topib ko'chirdi? (Rasmda saytning pastki qismi)", "correct_option_id": "a", "explanation": "Ko'p kompaniyalar saytining eng pastida (footer) yuridik ma'lumotlarni yozadi: manzil, STIR, MFO, OKED. Ustoz STIRni shu yerdan oldi.", "options": [{"id": "a", "text": "Saytning eng pastki qismidan (footer)"}, {"id": "b", "text": "Facebook sahifaning «О нас (About)» bo'limidan"}, {"id": "c", "text": "Gmail xatidan"}, {"id": "d", "text": "Instagram profilidan"}]}, {"id": "q7", "image": "images/3-3/q7.jpg", "prompt": "BM nomini «ROAS AGENCY» deb o'zgartirmoqchi bo'lganda xato chiqdi. Sababi nima?", "correct_option_id": "a", "explanation": "«Недопустимое название компании (Invalid business name)»: nom faqat katta harflardan iborat bo'lmasligi kerak. Facebook o'zi «ROAS Agency» ni taklif qildi, ustoz «Roas Agency» deb saqladi.", "options": [{"id": "a", "text": "Nom faqat KATTA harflardan yozilgan"}, {"id": "b", "text": "Nom juda uzun"}, {"id": "c", "text": "Bunday nomli BM allaqachon bor"}, {"id": "d", "text": "Nomda raqam yo'q"}]}, {"id": "q8", "image": "images/3-3/q8.jpg", "prompt": "«Центр безопасности (Security Center)» ochiq. Ikki bosqichli himoyani (2FA) BMdagi kim yoqishi shartligini qayerda belgilaysiz?", "correct_option_id": "a", "explanation": "A: «Кто должен включить двухфакторную аутентификацию? (Who must turn on two-factor authentication?)» ostidagi ro'yxat (Никто / Только админы / Все (No one / Only admins / Everyone)). Tavsiya: «Все (Everyone)» yoki kamida adminlar. B: «Добавить (Add)» — ikkinchi admin qo'shish, C: «Не подходит для подтверждения» — verifikatsiya holati, D: sarlavha.", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "keep_order": true}]$json$::jsonb, true) on conflict (id) do update set title = excluded.title, questions = excluded.questions, published = true;
insert into public.tests(id, section, section_order, lesson_order, title, questions, published) values ('3-4r', '3. Biznes menejer', 3, 4, '4. Adminlar qo''shish', $json$[{"id": "q1", "image": "images/3-4/q1.jpg", "prompt": "«Люди (People)» bo'limi ochiq. BMga yangi admin yoki xodim qo'shish uchun qayerni bosasiz?", "correct_option_id": "a", "explanation": "A: «Пригласить людей (Invite people)». B: «Партнеры (Partners)» — boshqa kompaniyalar, C: «Export» — ro'yxatni yuklab olish, D: mavjud odam qatori.", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "keep_order": true}, {"id": "q2", "image": "images/3-4/q2.jpg", "prompt": "Taklif yuborish uchun hamkasbingizning emailini so'radingiz. U rasmdagi «Контактная информация (Contact info)» oynasini ochdi. Nega aynan shu yerdagi emailni olish kerak?", "correct_option_id": "a", "explanation": "Taklif Facebook akkauntiga bog'langan emailga yuboriladi. U Facebook > Настройки и конфиденциальность > Центр аккаунтов > Личная информация > Контактная информация (Settings & privacy > Accounts Center > Personal details > Contact info)'da ko'rinadi.", "options": [{"id": "a", "text": "Taklif Facebook akkauntiga bog'langan emailga borishi kerak"}, {"id": "b", "text": "Bu email Gmail paroli bilan bir xil"}, {"id": "c", "text": "Bu email faqat Instagram uchun"}, {"id": "d", "text": "Bu yerdagi email reklama hisobiga kerak"}]}, {"id": "q3", "image": "images/3-4/q3.jpg", "prompt": "«Приглашение людей» oynasining 1-qadami. Taklif qilinadigan odamning emaili qayerga yoziladi?", "correct_option_id": "a", "explanation": "A: «Введите электронные адреса (Enter email addresses)» maydoni (bir nechta email vergul bilan yoziladi). B: «Далее (Next)», C: «Отмена», D: kompaniya ma'lumotlari taklif qilinganlarga ko'rinishi haqidagi izoh.", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "keep_order": true}, {"id": "q4", "image": "images/3-4/q4.jpg", "prompt": "2-qadam: ruxsatlar. Ishonchli sherigingizni TO'LIQ admin (hamma narsani boshqaradigan) qilmoqchisiz. Qaysi joyni o'zgartirasiz?", "correct_option_id": "a", "explanation": "A: «Полный доступ — Всё» ro'yxatidan «Управление (Manage)». B: «Приложения и интеграции», C: «Базовый доступ» (har doim yoqilgan), D: «Смотреть расширенные настройки» (Финансы).", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "keep_order": true}, {"id": "q5", "image": "images/3-4/q5.jpg", "prompt": "«Полный доступ — Управление» tanlanganda sariq ogohlantirish chiqdi. Ustoz nima maslahat berdi?", "correct_option_id": "a", "explanation": "To'liq kirish huquqini faqat juda ishonchli odamga bering: bunday admin boshqalarni (sizni ham) BMdan chiqarishi va BMni o'chirishi mumkin. Mijoz yoki xodimga odatda cheklangan kirish beriladi.", "options": [{"id": "a", "text": "To'liq kirishni faqat juda ishonchli odamga berish — u sizni ham chiqarib yuborishi mumkin"}, {"id": "b", "text": "Hammaga to'liq kirish berish kerak"}, {"id": "c", "text": "Bu ogohlantirishni e'tiborsiz qoldirish mumkin"}, {"id": "d", "text": "To'liq kirish faqat 24 soat ishlaydi"}]}, {"id": "q6", "image": "images/3-4/q6.jpg", "prompt": "3-qadam «Предоставление доступа (Give access)»: «В этой компании нет объектов типа Страницы» deb yozilgan. Ustoz nima qildi?", "correct_option_id": "a", "explanation": "BMda hali sahifa yo'q edi, shuning uchun obyekt tanlamasdan «Пригласить (Invite)» ni bosdi. Obyektlar (sahifa, reklama akkaunti) keyinroq «Назначить объекты» orqali biriktiriladi.", "options": [{"id": "a", "text": "Obyekt tanlamay «Пригласить (Invite)» ni bosdi, obyektlarni keyin biriktirdi"}, {"id": "b", "text": "Taklifni bekor qildi"}, {"id": "c", "text": "Avval yangi BM yaratdi"}, {"id": "d", "text": "Odamni o'chirib tashladi"}]}, {"id": "q7", "image": "images/3-4/q7.jpg", "prompt": "Taklif yuborildi. O'ngda «Объекты ещё не назначены» deb turibdi. Qizil ramkadagi tugma nima uchun?", "correct_option_id": "a", "explanation": "«Назначить объекты» — shu odamga sahifa, reklama akkaunti kabi obyektlarni biriktirish. Hozircha unga hech qanday obyekt berilmagan.", "options": [{"id": "a", "text": "Shu odamga sahifa / reklama akkauntini biriktirish"}, {"id": "b", "text": "Odamni BMdan o'chirish"}, {"id": "c", "text": "Taklifni qayta yuborish"}, {"id": "d", "text": "Parolni o'zgartirish"}]}, {"id": "q8", "image": "images/3-4/q8.jpg", "prompt": "Taklif qilingan odamning Gmail'iga rasmdagi xat keldi. Taklifni qabul qilishni boshlash uchun qayerni bosadi?", "correct_option_id": "a", "explanation": "A: «Начать (Get started)». Keyin ism kiritiladi, kompaniya ma'lumotlari tekshiriladi va «Принять приглашение (Accept invitation)» bosiladi. B: «Подробнее», C: jo'natuvchi (Facebook), D: xat sarlavhasi.", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "keep_order": true}, {"id": "q9", "image": "images/3-4/q9.jpg", "prompt": "Oxirgi qadam «Проверка (Review)». «Принять приглашение (Accept invitation)» bosilsa, kompaniyadagi hamkasblar nimani ko'radi?", "correct_option_id": "a", "explanation": "Ro'yxatning 1-bandi: hamkasblarga ismingiz, profil rasmingiz va Facebook ID'ingiz ko'rinadi. Kompaniya nomidan qilgan harakatlaringiz ham qayd qilinadi.", "options": [{"id": "a", "text": "Ismingiz, profil rasmingiz va Facebook ID'ingiz"}, {"id": "b", "text": "Shaxsiy xabarlaringiz"}, {"id": "c", "text": "Facebook parolingiz"}, {"id": "d", "text": "Do'stlaringiz ro'yxati"}]}, {"id": "q10", "image": "images/3-4/q10.jpg", "prompt": "Meta Business Suite'dagi «Люди (People)» ro'yxati. Taklif yuborilgan, lekin hali QABUL QILMAGAN odam qaysi?", "correct_option_id": "c", "explanation": "C: «Invited» — taklif yuborilgan, hali qabul qilinmagan. A: «Неактивный пользователь (Inactive user)» — qabul qilgan, lekin hali faol emas, B: «Активный (Active)» — faol foydalanuvchi, D: «Пригласить людей (Invite people)» tugmasi.", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "keep_order": true}]$json$::jsonb, true) on conflict (id) do update set title = excluded.title, questions = excluded.questions, published = true;
insert into public.tests(id, section, section_order, lesson_order, title, questions, published) values ('3-5r', '3. Biznes menejer', 3, 5, '5. Mijozlar akkauntini qo''shish', $json$[{"id": "q1", "image": "images/3-5/q1.jpg", "prompt": "Siz mijozsiz (kitchenshop.uz BM egasi). Agentlik sahifangizga reklama qilsin, lekin egasi siz bo'lib qolasiz. «Партнеры (Partners)» bo'limida qaysi tugmani bosasiz?", "correct_option_id": "a", "explanation": "A: «Партнеры, с которыми можно поделиться объектами» ostidagi «Добавить (Add)» — o'z obyektingizni partnyorga berish. B: «Партнеры, у которых можно запросить объекты» — boshqadan obyekt so'rash, C: «Партнеры (Partners)» menyusi, D: «Люди (People)».", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "keep_order": true}, {"id": "q2", "image": "images/3-5/q2.jpg", "prompt": "Agentlik mijozga o'zining BM ID'sini berishi kerak. U «Информация о компании (Business info)» sahifasining qayerida?", "correct_option_id": "a", "explanation": "A: «ID аккаунта Business Manager (Business Manager ID)» qatori. Mijoz shu raqamni «ID компании партнера (Partner business ID)» maydoniga yozadi. B: «Редактировать (Edit)», C: «Зарегистрированное название компании», D: «Сведения о компании (Business details)».", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "keep_order": true}, {"id": "q3", "image": "images/3-5/q3.jpg", "prompt": "Mijoz BMsida «Добавление нового партнера (Add a new partner)» oynasi ochildi. Agentlikning BM ID'si qayerga yoziladi?", "correct_option_id": "a", "explanation": "A: «ID компании-партнера» maydoni. B: «Далее (Next)», C: «Отмена», D: oynani yopish.", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "keep_order": true}, {"id": "q4", "image": "images/3-5/q4.jpg", "prompt": "«Назначение объектов и разрешений (Assign assets and permissions)»: Kitchen Shop sahifasi. Agentlik shu sahifa nomidan REKLAMA yurgizishi uchun qaysi tugmachani yoqasiz?", "correct_option_id": "b", "explanation": "B: «Реклама (Ads)». A: sahifani tanlash doirachasi, C: obyekt turi «Страницы (Pages)», D: «Сохранить изменения (Save changes)».", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "keep_order": true}, {"id": "q5", "image": "images/3-5/q5.jpg", "prompt": "Partnyorga Instagram akkauntni berishda rasmdagi oyna chiqdi. Qizil ramkadagi «Войти (Log in)» nima uchun kerak?", "correct_option_id": "a", "explanation": "Instagram akkauntga ruxsat berish uchun avval o'sha Instagram akkauntga kirish (login) kerak. Kirgach Instagram tanlanadi va ruxsatlar belgilanadi.", "options": [{"id": "a", "text": "Instagram akkauntingizga kirib, uni tasdiqlash uchun"}, {"id": "b", "text": "Facebook parolini o'zgartirish uchun"}, {"id": "c", "text": "Yangi Instagram ochish uchun"}, {"id": "d", "text": "Partnyorni o'chirish uchun"}]}, {"id": "q6", "image": "images/3-5/q6.jpg", "prompt": "Instagram ruxsatlari. Agentlik Direct'dagi xabarlarga javob bera olishi uchun qaysi tugmachani yoqasiz?", "correct_option_id": "b", "explanation": "B: «Сообщения» (Direct xabarlari). A: «Контент (Content)» — postlar, C: «Реклама (Ads)», D: «Статистика (Insights)».", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "keep_order": true}, {"id": "q7", "image": "images/3-5/q7.jpg", "prompt": "Mijoz BMsida (kitchenshop.uz) partnyor Roas Agency tanlangan. Mijoz agentlikka BERGAN obyektlarini qaysi tabda ko'radi?", "correct_option_id": "a", "explanation": "A: «Объекты, к которым вы предоставили доступ (Assets you've shared)» — siz bergan obyektlar (Kitchen Shop sahifasi va Instagram). B: «Общие объекты (Assets shared with you)» — sizga berilganlar, C: «Удалить (Remove)», D: «Предоставить доступ к объектам».", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "keep_order": true}, {"id": "q8", "image": "images/3-5/q8.jpg", "prompt": "Endi agentlik BMsida (Roas Agency) partnyor kitchenshop.uz tanlangan. Mijoz agentlikka bergan sahifa va Instagram qaysi tabda ko'rinadi?", "correct_option_id": "a", "explanation": "A: «Общие объекты (Assets shared with you)» — sizga ulashilgan obyektlar (Kitchen Shop, kitchenshop.uz). B: «Объекты, к которым вы предоставили доступ (Assets you've shared)» — siz bergan obyektlar (bo'sh), C: «Удалить (Remove)», D: «Добавить (Add)».", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "keep_order": true}, {"id": "q9", "image": "images/3-5/q9.jpg", "prompt": "Agentlik BMsida «Страницы (Pages)» bo'limida Kitchen Shop yonida «Принадлежит компании kitchenshop.uz (Owned by kitchenshop.uz)» yozuvi bor. Bu nimani bildiradi?", "correct_option_id": "a", "explanation": "Sahifaning egasi mijoz (kitchenshop.uz) bo'lib qoladi, agentlikda faqat berilgan ruxsatlar bor («Реклама, Статистика»). Mijoz xohlasa ruxsatni olib qo'yishi mumkin.", "options": [{"id": "a", "text": "Sahifa egasi mijoz, agentlikda faqat ruxsat bor"}, {"id": "b", "text": "Sahifa agentlikka butunlay o'tdi"}, {"id": "c", "text": "Sahifa bloklangan"}, {"id": "d", "text": "Sahifa o'chirilgan"}]}]$json$::jsonb, true) on conflict (id) do update set title = excluded.title, questions = excluded.questions, published = true;
insert into public.tests(id, section, section_order, lesson_order, title, questions, published) values ('3-6r', '3. Biznes menejer', 3, 6, '6. Sahifalarni boshqarish', $json$[{"id": "q1", "image": "images/3-6/q1.jpg", "prompt": "«Страницы (Pages)» > «Добавить (Add)» ro'yxati ochildi. MIJOZNING sahifasiga reklama qilish uchun ruxsat so'ramoqchisiz (egasi mijoz qoladi). Qaysi birini tanlaysiz?", "correct_option_id": "b", "explanation": "B: «Запросите доступ к Странице» — egasi o'zgarmaydi, siz faqat ruxsat olasiz. A: «Добавьте Страницу» — o'zingizning sahifangiz BMga o'tadi, C: «Создание новой Страницы (Create a new Page)» — yangi sahifa, D: «Показать Страницу».", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "keep_order": true}, {"id": "q2", "image": "images/3-6/q2.jpg", "prompt": "«Добавьте Страницу Facebook» oynasi. Bu usul bilan sahifa qo'shish uchun qanday shart bor?", "correct_option_id": "a", "explanation": "Matnda yozilgan: sahifani qo'shish uchun siz uning administratori bo'lishingiz kerak. Shunda so'rov avtomatik tasdiqlanadi va sahifa BMga o'tadi.", "options": [{"id": "a", "text": "Siz o'sha sahifaning administratori bo'lishingiz kerak"}, {"id": "b", "text": "Sahifada 1000 ta obunachi bo'lishi kerak"}, {"id": "c", "text": "Sahifa 1 yildan eski bo'lishi kerak"}, {"id": "d", "text": "Sahifaga reklama qilingan bo'lishi kerak"}]}, {"id": "q3", "image": "images/3-6/q3.jpg", "prompt": "Sahifa qo'shilgandan keyin «Требуется основная Страница (Primary Page required)» oynasi chiqdi. Asosiy sahifa nima uchun kerak?", "correct_option_id": "a", "explanation": "Matnda: boshqa kompaniyalarning sahifa, reklama akkaunti va resurslariga ruxsat so'rash uchun BMga asosiy sahifa kerak. U kompaniyani eng yaxshi ifodalaydigan sahifa bo'lishi kerak.", "options": [{"id": "a", "text": "Boshqa kompaniyalardan sahifa/reklama akkauntiga ruxsat so'rash uchun"}, {"id": "b", "text": "Instagram ulash uchun"}, {"id": "c", "text": "Karta qo'shish uchun"}, {"id": "d", "text": "Sahifani o'chirish uchun"}]}, {"id": "q4", "image": "images/3-6/q4.jpg", "prompt": "Boshqa sahifaga ruxsat so'raldi. Sariq ramkadagi «Ваш запрос ожидает одобрения (Your request is pending)» nimani bildiradi?", "correct_option_id": "a", "explanation": "So'rov sahifa administratoriga yuborildi va u tasdiqlashi kerak. Tasdiqlanmaguncha sahifaga odam biriktirib bo'lmaydi. Kerak bo'lsa «Отменить запрос (Cancel request)» bilan bekor qilinadi.", "options": [{"id": "a", "text": "Sahifa administratori so'rovni tasdiqlashi kerak"}, {"id": "b", "text": "Sahifa sizga o'tib bo'ldi"}, {"id": "c", "text": "Sahifa bloklandi"}, {"id": "d", "text": "Meta 48 soatda tekshiradi"}]}, {"id": "q5", "image": "images/3-6/q5.jpg", "prompt": "Yangi sahifa yaratyapsiz. Jizzaxdagi oddiy do'kon (manzili bor) uchun qaysi kategoriya to'g'ri keladi?", "correct_option_id": "a", "explanation": "A: «Местная компания или место (Local business or place)» — manzili bor mahalliy biznes. B: «Компания, организация или учреждение», C: «Марка или продукт (Brand or product)» — brend/mahsulot, D: «Развлечения».", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "keep_order": true}]$json$::jsonb, true) on conflict (id) do update set title = excluded.title, questions = excluded.questions, published = true;
insert into public.tests(id, section, section_order, lesson_order, title, questions, published) values ('3-7r', '3. Biznes menejer', 3, 7, '7. Reklama akkaunt ochish', $json$[{"id": "q1", "image": "images/3-7/q1.jpg", "prompt": "«Рекламные аккаунты (Ad accounts)» > «Добавить (Add)». BM uchun YANGI reklama akkaunti ochmoqchisiz. Qaysi birini tanlaysiz?", "correct_option_id": "c", "explanation": "C: «Создание рекламного аккаунта». A: «Добавить рекламный аккаунт (Add an ad account)» — o'zingizning mavjud akkauntingizni BMga ko'chirish (qaytarib bo'lmaydi), B: «Запросите доступ к рекламному аккаунту» — mijoz akkauntiga ruxsat so'rash, D: «Добавить (Add)» tugmasi.", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "keep_order": true}, {"id": "q2", "image": "images/3-7/q2.jpg", "prompt": "«Создание рекламного аккаунта» oynasi. Toshkent vaqtini (GMT+5) qayerda tanlaysiz?", "correct_option_id": "b", "explanation": "B: «Часовой пояс» (standart GMT-08:00 Los Angeles turadi, uni GMT+05:00 ga o'zgartirish kerak). A: akkaunt nomi, C: «Валюта», D: «Отмена».", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "keep_order": true}, {"id": "q3", "image": "images/3-7/q3.jpg", "prompt": "«Часовой пояс» ro'yxati ochiq. O'zbekiston uchun qaysi variantni tanlaysiz?", "correct_option_id": "a", "explanation": "Toshkent GMT+5. Ro'yxatda «(GMT+05:00) Asia/Tashkent» yoki «(GMT+05:00) Asia/Karachi» tanlanadi — ikkalasi ham +5 soat.", "options": [{"id": "a", "text": "(GMT+05:00) Asia/Tashkent yoki Asia/Karachi"}, {"id": "b", "text": "(GMT-08:00) America/Los_Angeles"}, {"id": "c", "text": "(GMT-06:00) America/Mexico_City"}, {"id": "d", "text": "(GMT+03:00) Europe/Moscow"}]}, {"id": "q4", "image": "images/3-7/q4.jpg", "prompt": "«Как будет использоваться этот рекламный аккаунт? (This ad account will be used for)» Akkauntni O'Z agentligingiz reklamasi uchun ochyapsiz. Qaysi variant?", "correct_option_id": "a", "explanation": "A: «Моя компания (Roas Agency)». B: «Другой компании или клиента (Another business or client)» — mijoz uchun, C: mavjud partnyorni tanlash, D: «Назад». To'g'ri tanlash muhim: «Почему я вижу эту рекламу? (Why am I seeing this ad?)» oynasida kimning nomi chiqishini belgilaydi.", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "keep_order": true}, {"id": "q5", "image": "images/3-7/q5.jpg", "prompt": "Akkauntga odam qo'shilyapti. U faqat reklama natijalari va hisobotlarni KO'RSIN, o'zgartira olmasin. Qaysi tugmachani yoqasiz?", "correct_option_id": "b", "explanation": "B: «Результативность» — faqat hisobot va ko'rish. A: «Управление кампаниями» — reklama yaratish/tahrirlash, C: «Управлять макетами в Креативном центре», D: «Управление рекламными аккаунтами» — to'liq nazorat.", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "keep_order": true}, {"id": "q6", "image": "images/3-7/q6.jpg", "prompt": "«Аккаунт создан!» chiqdi. Reklama yurgizishdan oldin keyingi qadam qaysi?", "correct_option_id": "a", "explanation": "A: «Добавить платежную информацию» — to'lov ma'lumotlari va karta qo'shish. B: «Закрыть», C: «Назначить людей (Assign people)», D: yangi akkaunt ID raqami.", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "keep_order": true}, {"id": "q7", "image": "images/3-7/q7.jpg", "prompt": "«Добавление платежной информации»: mamlakat, valyuta va vaqt mintaqasi. Qulf belgisi yonidagi yozuv nimani ogohlantiradi?", "correct_option_id": "a", "explanation": "«Настройки местоположения и валюты нельзя будет изменить» — bu sozlamalarni keyin o'zgartirib bo'lmaydi, shuning uchun diqqat bilan tanlang (Узбекистан, USD, GMT+5).", "options": [{"id": "a", "text": "Bu sozlamalarni keyin o'zgartirib bo'lmaydi"}, {"id": "b", "text": "Karta bloklangan"}, {"id": "c", "text": "Valyuta faqat so'm bo'lishi kerak"}, {"id": "d", "text": "Akkaunt yopildi"}]}, {"id": "q8", "image": "images/3-7/q8.jpg", "prompt": "STIR (НДС raqami) kiritildi va «Я юридическое лицо, зарегистрированное в Узбекистане (I'm a business registered in Uzbekistan)» belgilandi. Ustozning aytishicha, bu nima beradi?", "correct_option_id": "a", "explanation": "STIR kiritilib belgi qo'yilsa, Facebook har bir to'lovga 12% QQS qo'shmaydi — QQSni O'zbekistonda o'zingiz to'laysiz. Kiritilmasa, har to'lovga 12% qo'shib yechiladi.", "options": [{"id": "a", "text": "Facebook to'lovlarga 12% QQS qo'shmaydi"}, {"id": "b", "text": "Reklama bepul bo'ladi"}, {"id": "c", "text": "Kunlik limit oshadi"}, {"id": "d", "text": "Karta kerak bo'lmaydi"}]}, {"id": "q9", "image": "images/3-7/q9.jpg", "prompt": "«Биллинг и платежи (Billing & payments)» sahifasi. Meta yangi akkauntga qo'ygan KUNLIK sarf limiti qayerda ko'rinadi?", "correct_option_id": "b", "explanation": "B: «Дневной лимит затрат (установлен Meta): 50,00 $» — ishonch oshgach ko'payadi. A: «Порог оплаты $2,00» — shu summaga yetganda kartadan yechiladi, C: «Добавить средства» — oldindan to'lov, D: «Добавить способ оплаты».", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "keep_order": true}, {"id": "q10", "image": "images/3-7/q10.jpg", "prompt": "Ustoz «Лимит затрат для аккаунта (Account spending limit)» ga $1000 qo'ydi. Sarf shu summaga yetganda nima bo'ladi?", "correct_option_id": "a", "explanation": "Matnda: limitga yetganda reklama to'xtatiladi va limitni o'zgartirmaguningizcha ko'rsatilmaydi. Bu ortiqcha xarajatdan himoya qiladi.", "options": [{"id": "a", "text": "Reklama to'xtaydi"}, {"id": "b", "text": "Kartadan ikki baravar yechiladi"}, {"id": "c", "text": "Akkaunt o'chiriladi"}, {"id": "d", "text": "Limit o'z-o'zidan oshadi"}]}]$json$::jsonb, true) on conflict (id) do update set title = excluded.title, questions = excluded.questions, published = true;
insert into public.tests(id, section, section_order, lesson_order, title, questions, published) values ('3-8r', '3. Biznes menejer', 3, 8, '8. Instagram qo''shish', $json$[{"id": "q1", "image": "images/3-8/q1.jpg", "prompt": "«Аккаунты Instagram (Instagram accounts)» bo'limi. O'zingizning Instagram akkauntingizni BMga ulash uchun qayerni bosasiz?", "correct_option_id": "a", "explanation": "A: «Добавить (Add)». B: «Назначить людей (Assign people)» — odam biriktirish, C: «Убрать» — akkauntni olib tashlash, D: chap menyudagi «Аккаунты Instagram (Instagram accounts)» bo'limi (siz allaqachon shu yerdasiz).", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "keep_order": true}, {"id": "q2", "image": "images/3-8/q2.jpg", "prompt": "Ro'yxatdagi @kitchenshop.uz ostida «Владелец: kitchenshop.uz (Owned by: kitchenshop.uz)» yozilgan. Bu nimani bildiradi?", "correct_option_id": "a", "explanation": "Instagram egasi — mijozning BMsi (kitchenshop.uz). U partnyor orqali ulashilgan, Roas Agency'da faqat berilgan ruxsatlar bor (Статистика, Реклама, Сообщения...).", "options": [{"id": "a", "text": "Instagram egasi mijoz BMsi, sizda faqat ruxsatlar bor"}, {"id": "b", "text": "Instagram sizga butunlay o'tdi"}, {"id": "c", "text": "Akkaunt bloklangan"}, {"id": "d", "text": "Bu shaxsiy akkaunt"}]}, {"id": "q3", "image": "images/3-8/q3.jpg", "prompt": "«Добавление аккаунта Instagram (Add an Instagram account)» oynasi. Sariq ogohlantirishda nima deyilgan?", "correct_option_id": "a", "explanation": "BMga faqat PROFESSIONAL (biznes yoki autor) Instagram akkaunt qo'shiladi. Shaxsiy akkaunt qo'shilsa, u avtomatik professionalga o'zgartiriladi.", "options": [{"id": "a", "text": "Faqat professional akkaunt qo'shiladi; shaxsiy akkaunt professionalga o'zgaradi"}, {"id": "b", "text": "Instagram parolini o'zgartirish kerak"}, {"id": "c", "text": "Faqat 1000+ obunachisi bor akkaunt qo'shiladi"}, {"id": "d", "text": "Instagram 48 soatda tekshiriladi"}]}]$json$::jsonb, true) on conflict (id) do update set title = excluded.title, questions = excluded.questions, published = true;
insert into public.tests(id, section, section_order, lesson_order, title, questions, published) values ('3-9r', '3. Biznes menejer', 3, 9, '9. Domen verifikatsiyasi', $json$[{"id": "q1", "image": "images/3-9/q1.jpg", "prompt": "«Домены (Domains)» bo'limi bo'sh. Saytingiz domenini qo'shish uchun qayerni bosasiz?", "correct_option_id": "a", "explanation": "A: «Добавить» (keyin «Создание домена»). B: «Домены (Domains)» menyusi — siz shu yerdasiz, C: «Черные списки», D: «Безопасность бренда (Brand safety)» — domenlar shu bo'lim ichida.", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "keep_order": true}, {"id": "q2", "image": "images/3-9/q2.jpg", "prompt": "«Добавить домен (Add domain)» oynasi. Domen qanday yoziladi?", "correct_option_id": "a", "explanation": "Faqat domen nomi: planet-shop.uz. Oynada yozilgan: http:// yoki https:// prefikslari ishlatilmaydi, subdomen yoki alohida sahifa ham tasdiqlanmaydi.", "options": [{"id": "a", "text": "planet-shop.uz"}, {"id": "b", "text": "https://planet-shop.uz"}, {"id": "c", "text": "www.planet-shop.uz/"}, {"id": "d", "text": "planet-shop.uz/kontakt"}]}, {"id": "q3", "image": "images/3-9/q3.jpg", "prompt": "Domen qo'shildi, «Не подтвержден (Not verified)». Ustoz qaysi tasdiqlash usulini tanladi?", "correct_option_id": "a", "explanation": "«Добавьте мета-тег в исходный код HTML» — meta-teg usuli. Boshqa variantlar: HTML-faylni saytga yuklash yoki DNS'da TXT yozuvini yangilash.", "options": [{"id": "a", "text": "Meta-tegni saytning HTML kodiga qo'shish"}, {"id": "b", "text": "HTML-faylni yuklash"}, {"id": "c", "text": "DNS TXT yozuvini o'zgartirish"}, {"id": "d", "text": "Email orqali tasdiqlash"}]}, {"id": "q4", "image": "images/3-9/q4.jpg", "prompt": "Meta-teg ko'chirib olindi. U saytning qaysi qismiga qo'yiladi?", "correct_option_id": "a", "explanation": "2-band: meta-teg bosh sahifa HTML kodining <head> ... </head> qismiga qo'yiladi va sahifa qayta nashr qilinadi.", "options": [{"id": "a", "text": "Bosh sahifaning <head> ... </head> qismiga"}, {"id": "b", "text": "Saytning eng pastki (footer) qismiga"}, {"id": "c", "text": "Facebook sahifaning «О нас (About)» bo'limiga"}, {"id": "d", "text": "Domen nomining oxiriga"}]}, {"id": "q5", "image": "images/3-9/q5.jpg", "prompt": "Sayt Tilda'da qurilgan. «Настройки сайта» > «Еще (More)» ochiq. Meta-tegni qayerga qo'yasiz?", "correct_option_id": "a", "explanation": "A: «HTML-код для вставки внутрь HEAD» ostidagi «Редактировать код». Keyin saqlab, BARCHA sahifalar qayta nashr qilinadi. B: CSS uslublari, C: «Еще (More)» menyusi, D: 404 sahifa sozlamasi.", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "keep_order": true}, {"id": "q6", "image": "images/3-9/q6.jpg", "prompt": "Ikkinchi sayt WordPress'da. WPCode plaginining «Global Header and Footer» sahifasi. Meta-teg qaysi qutiga qo'yiladi?", "correct_option_id": "a", "explanation": "A: «Header» — bu yerdagi kod <head> qismiga chiqadi. B: «Body», C: «Save Changes» (qo'ygandan keyin bosiladi), D: chap menyudagi Code Snippets.", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "keep_order": true}, {"id": "q7", "image": "images/3-9/q7.jpg", "prompt": "Meta-teg qo'yildi, «Подтвердить домен (Verify domain)» bosildi, lekin Facebook kodni hali topmadi. Qancha kutish mumkin?", "correct_option_id": "a", "explanation": "Izohda: Facebook meta-teg kodini topishi uchun 72 soatgacha vaqt ketishi mumkin. Shundan keyin ham tasdiqlanmasa, «Подтвердить домен (Verify domain)» yana bosiladi.", "options": [{"id": "a", "text": "72 soatgacha"}, {"id": "b", "text": "5 daqiqa"}, {"id": "c", "text": "30 kun"}, {"id": "d", "text": "Darhol tasdiqlanishi shart"}]}, {"id": "q8", "image": "images/3-9/q8.jpg", "prompt": "Domen tasdiqlangandan keyingi sahifa. Domen tasdiqlanganini qayerdan bilasiz?", "correct_option_id": "a", "explanation": "A: yashil «Подтвержден (Verified)» yozuvi (avval qizil «Не подтвержден (Not verified)» edi). B: «Назначить партнеров», C: «Убрать» — domenni o'chirish, D: «Связанные объекты» tabi.", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "keep_order": true}]$json$::jsonb, true) on conflict (id) do update set title = excluded.title, questions = excluded.questions, published = true;
commit;
